-- SwiftDictionary Update 2.4.0 — owner-authorized production Quiz content release.
-- The owner explicitly approved publishing all 199 questions to production on 2026-11-17.
-- Manual bilingual accuracy review is deferred until live testing and friend feedback.
-- Database status 'approved' means selectable by Quiz; it is NOT a claim that human editorial review has occurred.
-- The source JSON remains status=draft so future edits continue through the reviewable authoring pipeline.
begin;

do $release_preflight$
declare
  v_count integer;
begin
  if to_regclass('private.quiz_question_bank') is null then
    raise exception 'Quiz question bank is missing; apply the 2.4.0 schema migrations first';
  end if;
  if exists (select 1 from private.quiz_question_bank) then
    raise exception 'Quiz release import requires an empty question bank; refusing to overwrite or mix content';
  end if;

  with expected(content_id,topic_id,difficulty) as (
    values
    ('a-hedging','academic-professional-english','advanced'),
    ('a-idioms','idioms-fixed-expressions','advanced'),
    ('a-inversion','advanced-grammar','advanced'),
    ('a-mixed-conditionals','advanced-grammar','advanced'),
    ('a-near-synonyms','precise-vocabulary','advanced'),
    ('b-articles','nouns-and-articles','beginner'),
    ('b-countable-nouns','nouns-and-quantity','beginner'),
    ('b-present','verb-tenses','beginner'),
    ('b-sentence','sentence-basics','beginner'),
    ('b-verb-combinations','everyday-vocabulary','beginner'),
    ('i-collocations','collocations','intermediate'),
    ('i-conditionals','conditional-sentences','intermediate'),
    ('i-perfect','verb-tenses','intermediate'),
    ('i-phrasal','phrasal-verbs','intermediate'),
    ('i-word-families','word-formation','intermediate')
  )
  select count(*)::integer into v_count
  from expected e
  join private.learning_content_catalog c
    on c.activity_type='permanent_lesson'
   and c.content_id=e.content_id
   and c.topic_id=e.topic_id
   and c.difficulty=e.difficulty
   and c.language_code='en'
   and c.is_active;
  if v_count<>15 then
    raise exception 'Quiz release aborted: expected all 15 active permanent lesson mappings; found %',v_count;
  end if;
end;
$release_preflight$;

insert into private.quiz_question_bank (
  question_id,revision,learning_language_code,translation_language_code,
  source_lesson_id,topic_id,difficulty,question_type,answer_language_code,
  learning_objective_id,prompt_learning,prompt_translation,options,
  correct_option_id,explanation_learning,explanation_translation,status,approved_at
) values
  ('quiz-beginner-001', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'knowledge', 'en', 'everyday-collocations', 'Choose the correct verb: Everyone can ___ a mistake when they are tired.', '选择正确的动词：人们疲倦时都可能___错误。', '[{"id":"a","learning_text":"do","translation_text":"做"},{"id":"b","learning_text":"take","translation_text":"拿/采取"},{"id":"c","learning_text":"make","translation_text":"犯/造成"},{"id":"d","learning_text":"have","translation_text":"有"}]'::jsonb, 'c', 'The standard collocation is “make a mistake.”', '标准搭配是“make a mistake”（犯错误）。', 'approved', pg_catalog.now()),
  ('quiz-beginner-002', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'knowledge', 'en', 'everyday-collocations', 'Which phrase means to stop working briefly and rest?', '哪个短语表示暂时停止工作并休息？', '[{"id":"a","learning_text":"make a break","translation_text":"制作一个休息"},{"id":"b","learning_text":"do a break","translation_text":"做一个休息"},{"id":"c","learning_text":"take a break","translation_text":"休息一下"},{"id":"d","learning_text":"hold a break","translation_text":"进行一次休息"}]'::jsonb, 'c', '“Take a break” is the standard expression for resting briefly.', '“Take a break”是表示短暂休息的标准表达。', 'approved', pg_catalog.now()),
  ('quiz-beginner-003', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'knowledge', 'en', 'everyday-collocations', 'Which phrase is commonly used to say that you eat the morning meal?', '哪个短语通常用来表示吃早饭？', '[{"id":"a","learning_text":"make breakfast","translation_text":"制作早餐"},{"id":"b","learning_text":"have breakfast","translation_text":"吃早餐"},{"id":"c","learning_text":"do breakfast","translation_text":"做早餐"},{"id":"d","learning_text":"cook breakfast","translation_text":"烹制早餐"}]'::jsonb, 'b', 'We commonly say “have breakfast” when talking about eating the morning meal.', '谈到吃早饭时，英语通常使用“have breakfast”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-004', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'knowledge', 'en', 'everyday-collocations', 'Complete the sentence: I ___ my homework after dinner.', '完成句子：我晚饭后___作业。', '[{"id":"a","learning_text":"make","translation_text":"制作"},{"id":"b","learning_text":"take","translation_text":"拿"},{"id":"c","learning_text":"do","translation_text":"做"},{"id":"d","learning_text":"have","translation_text":"拥有"}]'::jsonb, 'c', '“Do homework” is the usual verb-noun combination.', '“Do homework”是常见的动词与名词搭配。', 'approved', pg_catalog.now()),
  ('quiz-beginner-005', 1, 'en', 'zh', 'b-articles', 'nouns-and-articles', 'beginner', 'knowledge', 'en', 'article-use-and-sound', 'Choose the correct article: She bought ___ umbrella.', '选择正确的冠词：她买了一把雨伞。', '[{"id":"a","learning_text":"a","translation_text":"a"},{"id":"b","learning_text":"an","translation_text":"an"},{"id":"c","learning_text":"the","translation_text":"the"},{"id":"d","learning_text":"no article","translation_text":"不加冠词"}]'::jsonb, 'b', '“Umbrella” begins with a vowel sound, so the singular countable noun takes “an.”', '“Umbrella”以元音音素开头，因此单数可数名词前用“an”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-006', 1, 'en', 'zh', 'b-articles', 'nouns-and-articles', 'beginner', 'knowledge', 'en', 'article-use-and-sound', 'Choose the correct article: ___ sun rises in the east.', '选择正确的冠词：太阳从东方升起。', '[{"id":"a","learning_text":"A","translation_text":"A"},{"id":"b","learning_text":"An","translation_text":"An"},{"id":"c","learning_text":"The","translation_text":"The"},{"id":"d","learning_text":"No article","translation_text":"不加冠词"}]'::jsonb, 'c', 'We use “the” for the unique sun in this context.', '在这个语境中，太阳是独一无二的，因此使用“the”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-007', 1, 'en', 'zh', 'b-articles', 'nouns-and-articles', 'beginner', 'knowledge', 'en', 'article-use-and-sound', 'Choose the correct article: He studies at ___ university in Kuala Lumpur.', '选择正确的冠词：他在吉隆坡的一所大学学习。', '[{"id":"a","learning_text":"a","translation_text":"a"},{"id":"b","learning_text":"an","translation_text":"an"},{"id":"c","learning_text":"the","translation_text":"the"},{"id":"d","learning_text":"no article","translation_text":"不加冠词"}]'::jsonb, 'a', '“University” begins with the consonant sound /juː/, so “a” is correct.', '“University”以辅音音素 /j/ 开头，因此使用“a”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-008', 1, 'en', 'zh', 'b-articles', 'nouns-and-articles', 'beginner', 'knowledge', 'en', 'article-use-and-sound', 'Choose the correct article: It was ___ honest mistake.', '选择正确的冠词：那是一个无心的错误。', '[{"id":"a","learning_text":"a","translation_text":"a"},{"id":"b","learning_text":"an","translation_text":"an"},{"id":"c","learning_text":"the","translation_text":"the"},{"id":"d","learning_text":"no article","translation_text":"不加冠词"}]'::jsonb, 'b', 'The “h” in “honest” is silent, so the word begins with a vowel sound.', '“Honest”中的字母 h 不发音，因此该词以元音音素开头。', 'approved', pg_catalog.now()),
  ('quiz-beginner-009', 1, 'en', 'zh', 'b-countable-nouns', 'nouns-and-quantity', 'beginner', 'knowledge', 'en', 'countable-and-uncountable', 'Choose the correct plural form: one child, two ___.', '选择正确的复数形式：一个孩子，两个___。', '[{"id":"a","learning_text":"childs","translation_text":"childs"},{"id":"b","learning_text":"childes","translation_text":"childes"},{"id":"c","learning_text":"children","translation_text":"children"},{"id":"d","learning_text":"childrens","translation_text":"childrens"}]'::jsonb, 'c', '“Child” has the irregular plural form “children.”', '“Child”的不规则复数形式是“children”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-010', 1, 'en', 'zh', 'b-countable-nouns', 'nouns-and-quantity', 'beginner', 'knowledge', 'en', 'countable-and-uncountable', 'Which phrase is correct in standard English?', '以下哪个短语符合标准英语？', '[{"id":"a","learning_text":"an advice","translation_text":"an advice"},{"id":"b","learning_text":"a piece of advice","translation_text":"a piece of advice"},{"id":"c","learning_text":"many advice","translation_text":"many advice"},{"id":"d","learning_text":"two advices","translation_text":"two advices"}]'::jsonb, 'b', '“Advice” is uncountable in standard English; use “a piece of advice” for one item of advice.', '在标准英语中，“advice”是不可数名词；表示一条建议时可说“a piece of advice”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-011', 1, 'en', 'zh', 'b-countable-nouns', 'nouns-and-quantity', 'beginner', 'knowledge', 'en', 'countable-and-uncountable', 'Choose the correct word: How ___ apples do we need?', '选择正确的词：我们需要多少个苹果？', '[{"id":"a","learning_text":"much","translation_text":"多少（不可数）"},{"id":"b","learning_text":"many","translation_text":"多少（可数复数）"},{"id":"c","learning_text":"any","translation_text":"任何"},{"id":"d","learning_text":"little","translation_text":"少量"}]'::jsonb, 'b', '“Apples” is a plural countable noun, so the question uses “many.”', '“Apples”是可数名词复数，因此疑问句使用“many”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-012', 1, 'en', 'zh', 'b-countable-nouns', 'nouns-and-quantity', 'beginner', 'knowledge', 'en', 'countable-and-uncountable', 'Choose the correct word: There isn''t ___ water in the bottle.', '选择正确的词：瓶子里没有多少水。', '[{"id":"a","learning_text":"many","translation_text":"许多（用于可数名词）"},{"id":"b","learning_text":"a few","translation_text":"少数几个"},{"id":"c","learning_text":"much","translation_text":"多少（用于不可数名词）"},{"id":"d","learning_text":"several","translation_text":"好几个"}]'::jsonb, 'c', '“Water” is uncountable here, so “much” is used in this negative sentence.', '这里的“water”是不可数名词，因此否定句中使用“much”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-013', 1, 'en', 'zh', 'b-sentence', 'sentence-basics', 'beginner', 'knowledge', 'en', 'basic-sentence-structure', 'Which sentence follows the usual subject–verb–object order?', '哪个句子符合常见的主语—动词—宾语语序？', '[{"id":"a","learning_text":"Reads Mia a book.","translation_text":"读一本书 Mia。"},{"id":"b","learning_text":"Mia a book reads.","translation_text":"Mia 一本书 读。"},{"id":"c","learning_text":"A book Mia reads.","translation_text":"一本书 Mia 读。"},{"id":"d","learning_text":"Mia reads a book.","translation_text":"Mia 读一本书。"}]'::jsonb, 'd', '“Mia” is the subject, “reads” is the verb, and “a book” is the object.', '“Mia”是主语，“reads”是动词，“a book”是宾语。', 'approved', pg_catalog.now()),
  ('quiz-beginner-014', 1, 'en', 'zh', 'b-sentence', 'sentence-basics', 'beginner', 'knowledge', 'en', 'basic-sentence-structure', 'Choose the correct word order.', '选择正确的词序。', '[{"id":"a","learning_text":"They are at home.","translation_text":"他们在家。"},{"id":"b","learning_text":"Are they home at.","translation_text":"在家他们是。"},{"id":"c","learning_text":"At home are they.","translation_text":"在家是他们。"},{"id":"d","learning_text":"They at are home.","translation_text":"他们在是家。"}]'::jsonb, 'a', 'The usual statement order is subject + verb + place phrase.', '常见陈述句语序是主语 + 动词 + 地点短语。', 'approved', pg_catalog.now()),
  ('quiz-beginner-015', 1, 'en', 'zh', 'b-sentence', 'sentence-basics', 'beginner', 'knowledge', 'en', 'basic-sentence-structure', 'Choose the simple-present question that correctly uses “does” with “he” and asks about working here.', '选择正确的疑问句。', '[{"id":"a","learning_text":"Does he work there?","translation_text":"他在那边工作吗？"},{"id":"b","learning_text":"Do they work here?","translation_text":"他们在这里工作吗？"},{"id":"c","learning_text":"Does he work here?","translation_text":"他在这里工作吗？"},{"id":"d","learning_text":"Is he working here?","translation_text":"他现在正在这里工作吗？"}]'::jsonb, 'c', 'With “does,” the main verb stays in its base form: “work.”', '使用“does”时，主要动词保持原形“work”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-016', 1, 'en', 'zh', 'b-sentence', 'sentence-basics', 'beginner', 'knowledge', 'en', 'basic-sentence-structure', 'Choose the sentence with the usual adjective position.', '选择形容词位置通常正确的句子。', '[{"id":"a","learning_text":"She has a bag red.","translation_text":"她有一个包红色的。"},{"id":"b","learning_text":"She has red a bag.","translation_text":"她有红色一个包。"},{"id":"c","learning_text":"She has a red bag.","translation_text":"她有一个红色的包。"},{"id":"d","learning_text":"Red she has a bag.","translation_text":"红色她有一个包。"}]'::jsonb, 'c', 'In this noun phrase, the adjective “red” comes before the noun “bag.”', '在这个名词短语中，形容词“red”放在名词“bag”之前。', 'approved', pg_catalog.now()),
  ('quiz-beginner-017', 1, 'en', 'zh', 'b-present', 'verb-tenses', 'beginner', 'knowledge', 'en', 'present-simple-routines', 'Choose the correct present simple form: My brother ___ to school by bus.', '选择正确的一般现在时形式：我哥哥/弟弟乘公共汽车去上学。', '[{"id":"a","learning_text":"go","translation_text":"去"},{"id":"b","learning_text":"goes","translation_text":"去（第三人称单数）"},{"id":"c","learning_text":"going","translation_text":"正在去"},{"id":"d","learning_text":"gone","translation_text":"已经去"}]'::jsonb, 'b', 'With a third-person singular subject such as “my brother,” the present simple verb takes -s or -es.', '主语是“my brother”这样的第三人称单数时，一般现在时动词通常加 -s 或 -es。', 'approved', pg_catalog.now()),
  ('quiz-beginner-018', 1, 'en', 'zh', 'b-present', 'verb-tenses', 'beginner', 'knowledge', 'en', 'present-simple-routines', 'Choose the grammatically correct negative sentence about coffee.', '选择正确的否定句。', '[{"id":"a","learning_text":"They doesn''t like milk.","translation_text":"他们不喜欢牛奶。"},{"id":"b","learning_text":"They not like tea.","translation_text":"他们不喜欢茶。"},{"id":"c","learning_text":"They don''t likes juice.","translation_text":"他们不喜欢果汁。"},{"id":"d","learning_text":"They don''t like coffee.","translation_text":"他们不喜欢咖啡。"}]'::jsonb, 'd', 'With “they,” use “do not/don''t” followed by the base form “like.”', '主语是“they”时，使用“do not/don''t”加动词原形“like”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-019', 1, 'en', 'zh', 'b-present', 'verb-tenses', 'beginner', 'knowledge', 'en', 'present-simple-routines', 'Choose the correct present-simple sentence that describes a regular habit.', '选择描述习惯的正确一般现在时句子。', '[{"id":"a","learning_text":"She walks to work every day.","translation_text":"她每天步行去上班。"},{"id":"b","learning_text":"She walked to work yesterday.","translation_text":"她昨天步行去上班。"},{"id":"c","learning_text":"She is walking to work now.","translation_text":"她现在正步行去上班。"},{"id":"d","learning_text":"She will walk to work tomorrow.","translation_text":"她明天会步行去上班。"}]'::jsonb, 'a', '“Every day” describes a regular habit, and “she” takes the verb form “walks.”', '“Every day”表示规律习惯；主语“she”对应动词形式“walks”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-020', 1, 'en', 'zh', 'b-present', 'verb-tenses', 'beginner', 'knowledge', 'en', 'present-simple-routines', 'Complete the sentence: We ___ dinner at home on Fridays.', '完成句子：我们星期五在家吃晚饭。', '[{"id":"a","learning_text":"has","translation_text":"有/吃（第三人称单数）"},{"id":"b","learning_text":"having","translation_text":"正在吃"},{"id":"c","learning_text":"have","translation_text":"有/吃"},{"id":"d","learning_text":"had","translation_text":"过去吃了"}]'::jsonb, 'c', '“We” takes the base present simple form “have.”', '主语“We”使用一般现在时动词原形“have”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-021', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'knowledge', 'en', 'everyday-collocations', 'Choose the correct verb: Please ___ attention to the road.', '选择正确的动词：请注意路况。', '[{"id":"a","learning_text":"make","translation_text":"制作"},{"id":"b","learning_text":"do","translation_text":"做"},{"id":"c","learning_text":"pay","translation_text":"给予/支付"},{"id":"d","learning_text":"take","translation_text":"拿"}]'::jsonb, 'c', 'The standard expression is “pay attention.”', '标准表达是“pay attention”（注意）。', 'approved', pg_catalog.now()),
  ('quiz-beginner-022', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'knowledge', 'en', 'everyday-collocations', 'Which phrase means to do what you promised?', '哪个短语表示履行自己的承诺？', '[{"id":"a","learning_text":"make a promise","translation_text":"作出承诺"},{"id":"b","learning_text":"keep a promise","translation_text":"遵守承诺"},{"id":"c","learning_text":"break a promise","translation_text":"违背承诺"},{"id":"d","learning_text":"take a promise","translation_text":"拿一个承诺"}]'::jsonb, 'b', '“Keep a promise” means to do what you said you would do.', '“Keep a promise”表示履行自己作出的承诺。', 'approved', pg_catalog.now()),
  ('quiz-beginner-023', 1, 'en', 'zh', 'b-articles', 'nouns-and-articles', 'beginner', 'knowledge', 'en', 'article-use-and-sound', 'Choose the correct article: It took us ___ hour to reach the station.', '选择正确的冠词：我们花了一个小时到达车站。', '[{"id":"a","learning_text":"a","translation_text":"a"},{"id":"b","learning_text":"the","translation_text":"the"},{"id":"c","learning_text":"no article","translation_text":"不加冠词"},{"id":"d","learning_text":"an","translation_text":"an"}]'::jsonb, 'd', 'The “h” in “hour” is silent, so the word begins with a vowel sound and takes “an.”', '“Hour”中的 h 不发音，因此该词以元音音素开头，使用“an”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-024', 1, 'en', 'zh', 'b-articles', 'nouns-and-articles', 'beginner', 'knowledge', 'en', 'article-use-and-sound', 'Choose the correct article: She bought ___ useful dictionary.', '选择正确的冠词：她买了一本有用的词典。', '[{"id":"a","learning_text":"an","translation_text":"an"},{"id":"b","learning_text":"a","translation_text":"a"},{"id":"c","learning_text":"the","translation_text":"the"},{"id":"d","learning_text":"no article","translation_text":"不加冠词"}]'::jsonb, 'b', '“Useful” begins with the consonant sound /j/, so the correct article is “a.”', '“Useful”以辅音音素 /j/ 开头，因此使用“a”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-025', 1, 'en', 'zh', 'b-countable-nouns', 'nouns-and-quantity', 'beginner', 'knowledge', 'en', 'countable-and-uncountable', 'Complete the sentence: There are two ___ of bread on the plate.', '完成句子：盘子里有两___面包。', '[{"id":"a","learning_text":"slice","translation_text":"片"},{"id":"b","learning_text":"slices","translation_text":"片（复数）"},{"id":"c","learning_text":"breads","translation_text":"面包（复数）"},{"id":"d","learning_text":"loafs","translation_text":"loafs"}]'::jsonb, 'b', '“Two” requires a plural countable unit; “two slices of bread” is correct.', '“Two”后需要可数名词复数；“two slices of bread”是正确表达。', 'approved', pg_catalog.now()),
  ('quiz-beginner-026', 1, 'en', 'zh', 'b-countable-nouns', 'nouns-and-quantity', 'beginner', 'knowledge', 'en', 'countable-and-uncountable', 'Choose the uncountable noun: How much ___ do we need for the recipe?', '选择不可数名词：这个食谱需要多少___？', '[{"id":"a","learning_text":"eggs","translation_text":"鸡蛋"},{"id":"b","learning_text":"carrots","translation_text":"胡萝卜"},{"id":"c","learning_text":"sugar","translation_text":"糖"},{"id":"d","learning_text":"apples","translation_text":"苹果"}]'::jsonb, 'c', '“Sugar” is uncountable in this context, so it fits the question with “much.”', '在此语境中，“sugar”是不可数名词，因此可与“much”搭配。', 'approved', pg_catalog.now()),
  ('quiz-beginner-027', 1, 'en', 'zh', 'b-sentence', 'sentence-basics', 'beginner', 'knowledge', 'en', 'basic-sentence-structure', 'Choose the correct sentence: ___ three chairs in the room.', '选择正确的句子：房间里有三把椅子。', '[{"id":"a","learning_text":"There is","translation_text":"房间里有一把椅子。"},{"id":"b","learning_text":"It are","translation_text":"它们是三把椅子。"},{"id":"c","learning_text":"There are","translation_text":"房间里有三把椅子。"},{"id":"d","learning_text":"They has","translation_text":"它们有三把椅子。"}]'::jsonb, 'c', '“Three chairs” is plural, so the correct structure is “There are.”', '“Three chairs”是复数，因此正确结构是“There are”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-028', 1, 'en', 'zh', 'b-sentence', 'sentence-basics', 'beginner', 'knowledge', 'en', 'basic-sentence-structure', 'Choose the correct word to begin this present simple question: ___ you like music?', '选择正确的词来开头，构成一般现在时疑问句：你喜欢音乐吗？', '[{"id":"a","learning_text":"Does","translation_text":"助动词（第三人称单数）"},{"id":"b","learning_text":"Do","translation_text":"助动词（I/you/we/they）"},{"id":"c","learning_text":"Are","translation_text":"be动词复数/第二人称"},{"id":"d","learning_text":"Is","translation_text":"be动词单数"}]'::jsonb, 'b', 'For a present simple question with the subject “you,” use the auxiliary “do.”', '一般现在时中，主语是“you”的疑问句使用助动词“do”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-029', 1, 'en', 'zh', 'b-present', 'verb-tenses', 'beginner', 'knowledge', 'en', 'present-simple-routines', 'Choose the correct present simple form: The shop ___ at nine every morning.', '选择正确的一般现在时形式：这家商店每天早上九点开门。', '[{"id":"a","learning_text":"open","translation_text":"开门"},{"id":"b","learning_text":"opening","translation_text":"正在开门"},{"id":"c","learning_text":"opens","translation_text":"开门（第三人称单数）"},{"id":"d","learning_text":"opened","translation_text":"开了（过去式）"}]'::jsonb, 'c', '“The shop” is third-person singular, so the present simple verb takes -s.', '“The shop”是第三人称单数，因此一般现在时动词加 -s。', 'approved', pg_catalog.now()),
  ('quiz-beginner-030', 1, 'en', 'zh', 'b-present', 'verb-tenses', 'beginner', 'knowledge', 'en', 'present-simple-routines', 'Which sentence uses “usually” before the main verb and says that she drinks tea in the evening?', '哪个句子把频率副词放在主要动词之前，也就是它通常的位置？', '[{"id":"a","learning_text":"She usually drinks tea in the morning.","translation_text":"她通常早上喝茶。"},{"id":"b","learning_text":"She drinks usually tea in the evening.","translation_text":"她在晚上通常喝茶（副词位置不自然）。"},{"id":"c","learning_text":"She usually drinks tea in the evening.","translation_text":"她通常在晚上喝茶。"},{"id":"d","learning_text":"She drinks tea in the evening every day.","translation_text":"她每天晚上喝茶。"}]'::jsonb, 'c', 'Adverbs of frequency such as usually normally appear before the main verb: She usually drinks tea in the evening.', 'Usually 等频率副词通常放在主要动词之前：She usually drinks tea in the evening。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-001', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'knowledge', 'en', 'natural-collocations', 'The new training programme should help employees ___ progress in their communication skills.', '新的培训计划应该帮助员工在沟通技巧方面取得进步。', '[{"id":"a","learning_text":"do","translation_text":"做"},{"id":"b","learning_text":"take","translation_text":"拿/采取"},{"id":"c","learning_text":"make","translation_text":"取得/制造"},{"id":"d","learning_text":"have","translation_text":"拥有"}]'::jsonb, 'c', 'The standard collocation is “make progress.”', '标准搭配是“make progress”（取得进步）。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-002', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'knowledge', 'en', 'natural-collocations', 'The outdoor event was canceled because of ___ rain.', '由于下大雨，户外活动被取消了。', '[{"id":"a","learning_text":"heavy","translation_text":"大的/沉重的"},{"id":"b","learning_text":"powerful","translation_text":"强大的"},{"id":"c","learning_text":"thick","translation_text":"厚的"},{"id":"d","learning_text":"solid","translation_text":"坚固的"}]'::jsonb, 'a', 'English commonly uses “heavy rain” for rain falling in large amounts.', '英语通常用“heavy rain”表示雨量很大。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-003', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'knowledge', 'en', 'natural-collocations', 'Which verb means to complete work by the required date: ___ the deadline?', '哪个动词表示在规定日期前完成工作：___ 截止日期？', '[{"id":"a","learning_text":"meet","translation_text":"达到/满足"},{"id":"b","learning_text":"miss","translation_text":"错过"},{"id":"c","learning_text":"extend","translation_text":"延长"},{"id":"d","learning_text":"cancel","translation_text":"取消"}]'::jsonb, 'a', '“Meet the deadline” means to finish the work by the required date.', '“Meet the deadline”表示在规定日期前完成工作。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-004', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'knowledge', 'en', 'natural-collocations', 'During the meeting, Maya ___ an important issue about customer support.', '会议期间，Maya提出了一个有关客户支持的重要问题。', '[{"id":"a","learning_text":"raised","translation_text":"提出"},{"id":"b","learning_text":"rose","translation_text":"上升"},{"id":"c","learning_text":"grew","translation_text":"成长/增长"},{"id":"d","learning_text":"lifted","translation_text":"举起"}]'::jsonb, 'a', '“Raise an issue” means to bring a problem or subject to people''s attention.', '“Raise an issue”表示提出问题或让大家注意某个议题。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-005', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'knowledge', 'en', 'natural-collocations', 'Given the clear weather forecast, it is ___ that the outdoor concert will be canceled.', '考虑到天气预报显示天气晴朗，户外音乐会被取消的可能性很小。', '[{"id":"a","learning_text":"strongly unlikely","translation_text":"强烈地不可能"},{"id":"b","learning_text":"deeply unlikely","translation_text":"深深地不可能"},{"id":"c","learning_text":"highly unlikely","translation_text":"极不可能"},{"id":"d","learning_text":"heavily unlikely","translation_text":"沉重地不可能"}]'::jsonb, 'c', '“Highly unlikely” is the natural collocation meaning very improbable.', '“Highly unlikely”是自然搭配，表示极不可能。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-006', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'knowledge', 'en', 'natural-collocations', 'Every team member must ___ responsibility for checking their own work.', '每位团队成员都必须为检查自己的工作承担责任。', '[{"id":"a","learning_text":"make","translation_text":"制造"},{"id":"b","learning_text":"do","translation_text":"做"},{"id":"c","learning_text":"take","translation_text":"承担"},{"id":"d","learning_text":"hold","translation_text":"持有"}]'::jsonb, 'c', 'The standard expression is “take responsibility for” something.', '标准表达是“take responsibility for”（对某事承担责任）。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-007', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'knowledge', 'en', 'natural-collocations', 'The sudden drop in sales could ___ a serious problem for the business.', '销售额突然下降可能会给企业带来严重问题。', '[{"id":"a","learning_text":"pose","translation_text":"构成/造成"},{"id":"b","learning_text":"do","translation_text":"做"},{"id":"c","learning_text":"take","translation_text":"拿"},{"id":"d","learning_text":"make","translation_text":"制作"}]'::jsonb, 'a', '“Pose a problem” means to create or present a problem.', '“Pose a problem”表示造成或带来问题。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-008', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'knowledge', 'en', 'natural-collocations', 'The manager was ___ concerned about the safety report and asked for a review.', '经理非常关注安全报告，并要求重新审查。', '[{"id":"a","learning_text":"deeply","translation_text":"深切地"},{"id":"b","learning_text":"broadly","translation_text":"广泛地"},{"id":"c","learning_text":"narrowly","translation_text":"狭窄地"},{"id":"d","learning_text":"loosely","translation_text":"松散地"}]'::jsonb, 'a', '“Deeply concerned” is a common collocation expressing serious worry.', '“Deeply concerned”是常见搭配，表示非常担忧。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-009', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'knowledge', 'en', 'conditional-meaning-and-forms', 'Choose the correct completion: If the weather improves tomorrow, we ___ the match outside.', '选择正确的句子补全：如果明天天气好转，我们将在户外比赛。', '[{"id":"a","learning_text":"held","translation_text":"举行（过去式）"},{"id":"b","learning_text":"will hold","translation_text":"将举行"},{"id":"c","learning_text":"would hold","translation_text":"会举行（假设）"},{"id":"d","learning_text":"have held","translation_text":"已经举行"}]'::jsonb, 'b', 'A first conditional uses a present-tense if-clause and “will” for a likely future result.', '第一条件句通常在 if 从句中使用现在时，并在可能发生的未来结果中使用“will”。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-010', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'knowledge', 'en', 'conditional-meaning-and-forms', 'Choose the correct completion: If I ___ closer to the office, I would walk to work.', '选择正确的句子补全：如果我住得离办公室更近，我就会步行上班。', '[{"id":"a","learning_text":"live","translation_text":"居住（现在时）"},{"id":"b","learning_text":"will live","translation_text":"将居住"},{"id":"c","learning_text":"lived","translation_text":"居住（过去式）"},{"id":"d","learning_text":"had lived","translation_text":"曾经居住"}]'::jsonb, 'c', 'The second conditional uses the past simple in the if-clause for an unreal or unlikely present situation.', '第二条件句用一般过去时表达不真实或不太可能发生的现在情况。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-011', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'knowledge', 'en', 'conditional-meaning-and-forms', 'Complete the sentence: ___ you leave now, you will miss the last train.', '完成句子：如果你现在不出发，就会错过末班车。', '[{"id":"a","learning_text":"Although","translation_text":"虽然"},{"id":"b","learning_text":"Unless","translation_text":"除非/如果不"},{"id":"c","learning_text":"Because","translation_text":"因为"},{"id":"d","learning_text":"While","translation_text":"当……时"}]'::jsonb, 'b', '“Unless” means “if not,” so it expresses the condition that you do not leave now.', '“Unless”表示“如果不”，这里指如果你现在不出发。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-012', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'knowledge', 'en', 'conditional-meaning-and-forms', 'Choose the correct zero conditional sentence about a general fact.', '选择描述一般事实的正确零条件句。', '[{"id":"a","learning_text":"If you heat ice, it melts.","translation_text":"如果加热冰，冰就会融化。"},{"id":"b","learning_text":"If you heated ice, it will melt.","translation_text":"如果你加热冰，它将融化。"},{"id":"c","learning_text":"If you heat ice, it would melt.","translation_text":"如果你加热冰，它会融化。"},{"id":"d","learning_text":"If you will heat ice, it melts.","translation_text":"如果你将加热冰，它就会融化。"}]'::jsonb, 'a', 'The zero conditional uses present simple in both clauses for general facts.', '零条件句通常在两个分句中都使用一般现在时来表达普遍事实。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-013', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'knowledge', 'en', 'conditional-meaning-and-forms', 'Choose the correct third conditional completion: If they had booked earlier, they ___ less.', '选择正确的第三条件句补全：如果他们早点预订，他们当时就会花更少的钱。', '[{"id":"a","learning_text":"would pay","translation_text":"会支付"},{"id":"b","learning_text":"will have paid","translation_text":"将已经支付"},{"id":"c","learning_text":"would have paid","translation_text":"本来会支付"},{"id":"d","learning_text":"had paid","translation_text":"已经支付（过去完成时）"}]'::jsonb, 'c', 'The third conditional uses “would have” plus a past participle for an unreal past result.', '第三条件句用“would have”加过去分词表示与过去事实相反的结果。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-014', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'knowledge', 'en', 'conditional-meaning-and-forms', 'Choose the phrase that correctly completes the sentence: You may use the meeting room ___ you leave it clean.', '选择正确的短语补全句子：只要你保持会议室整洁，就可以使用它。', '[{"id":"a","learning_text":"even though","translation_text":"即使"},{"id":"b","learning_text":"as soon as","translation_text":"一……就……"},{"id":"c","learning_text":"provided that","translation_text":"只要"},{"id":"d","learning_text":"in case","translation_text":"以防"}]'::jsonb, 'c', '“Provided that” introduces a condition that must be met.', '“Provided that”引出必须满足的条件，意思是“只要”。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-015', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'knowledge', 'en', 'conditional-meaning-and-forms', 'Choose the correct mixed conditional: If I had accepted the offer, I ___ in Singapore now.', '选择正确的混合条件句：如果我当时接受了那份工作，我现在就会住在新加坡。', '[{"id":"a","learning_text":"would live","translation_text":"会住（一般假设）"},{"id":"b","learning_text":"would be living","translation_text":"现在会住着"},{"id":"c","learning_text":"will be living","translation_text":"将会住着"},{"id":"d","learning_text":"had lived","translation_text":"曾经住过"}]'::jsonb, 'b', 'The past perfect describes the unreal past condition; “would be living” describes its present result.', '过去完成时描述与过去事实相反的条件；“would be living”描述它在现在产生的结果。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-016', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'knowledge', 'en', 'phrasal-verbs-in-context', 'Could you ___ my dog while I am away this weekend?', '这个周末我不在时，你能帮我照看我的狗吗？', '[{"id":"a","learning_text":"look after","translation_text":"照顾"},{"id":"b","learning_text":"look into","translation_text":"调查"},{"id":"c","learning_text":"look over","translation_text":"检查"},{"id":"d","learning_text":"look up","translation_text":"查找"}]'::jsonb, 'a', '“Look after” means to take care of a person or animal.', '“Look after”表示照顾某人或动物。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-017', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'knowledge', 'en', 'phrasal-verbs-in-context', 'The meeting was ___ until next Monday because the director was ill.', '由于主管生病，会议被推迟到下周一。', '[{"id":"a","learning_text":"put out","translation_text":"扑灭/熄灭"},{"id":"b","learning_text":"put off","translation_text":"推迟"},{"id":"c","learning_text":"put up","translation_text":"张贴/举起"},{"id":"d","learning_text":"put through","translation_text":"接通电话"}]'::jsonb, 'b', '“Put off” means to postpone an event or activity.', '“Put off”表示推迟活动或事件。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-018', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'knowledge', 'en', 'phrasal-verbs-in-context', 'We need to buy more milk because we have ___ it.', '我们需要再买一些牛奶，因为牛奶已经用完了。', '[{"id":"a","learning_text":"run into","translation_text":"偶遇/撞上"},{"id":"b","learning_text":"run over","translation_text":"碾过/复习"},{"id":"c","learning_text":"run out of","translation_text":"用完"},{"id":"d","learning_text":"run after","translation_text":"追赶"}]'::jsonb, 'c', '“Run out of” means to have no more of something available.', '“Run out of”表示某物已经用完。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-019', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'knowledge', 'en', 'phrasal-verbs-in-context', 'Despite the interruption, the speaker ___ explaining the results.', '尽管被打断，演讲者还是继续解释结果。', '[{"id":"a","learning_text":"carried on","translation_text":"继续"},{"id":"b","learning_text":"carried out","translation_text":"执行"},{"id":"c","learning_text":"carried away","translation_text":"冲昏头脑"},{"id":"d","learning_text":"carried off","translation_text":"成功完成/带走"}]'::jsonb, 'a', '“Carry on” means to continue doing something.', '“Carry on”表示继续做某事。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-020', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'knowledge', 'en', 'phrasal-verbs-in-context', 'At the end of the interview, the candidate ___ an important question about training.', '面试快结束时，候选人提出了一个有关培训的重要问题。', '[{"id":"a","learning_text":"brought up","translation_text":"提出/提起"},{"id":"b","learning_text":"brought about","translation_text":"引起"},{"id":"c","learning_text":"brought back","translation_text":"带回/使回忆"},{"id":"d","learning_text":"brought down","translation_text":"降低/击落"}]'::jsonb, 'a', '“Bring up” means to mention a topic for discussion.', '“Bring up”表示提出一个话题供讨论。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-021', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'knowledge', 'en', 'phrasal-verbs-in-context', 'She ___ the job offer because the position required frequent travel.', '她拒绝了这份工作邀请，因为该职位需要经常出差。', '[{"id":"a","learning_text":"turned on","translation_text":"打开/攻击"},{"id":"b","learning_text":"turned up","translation_text":"出现/调高"},{"id":"c","learning_text":"turned down","translation_text":"拒绝/调低"},{"id":"d","learning_text":"turned into","translation_text":"变成"}]'::jsonb, 'c', '“Turn down” means to reject an offer or request.', '“Turn down”表示拒绝提议或请求。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-022', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'knowledge', 'en', 'phrasal-verbs-in-context', 'I usually ___ my new colleagues because we communicate openly and respectfully.', '我通常和新同事相处融洽，因为我们沟通坦诚且互相尊重。', '[{"id":"a","learning_text":"get over","translation_text":"克服"},{"id":"b","learning_text":"get along with","translation_text":"与……相处融洽"},{"id":"c","learning_text":"get away with","translation_text":"侥幸逃脱"},{"id":"d","learning_text":"get through","translation_text":"完成/接通"}]'::jsonb, 'b', '“Get along with” describes having a friendly or successful relationship with someone.', '“Get along with”表示与某人关系融洽。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-023', 1, 'en', 'zh', 'i-perfect', 'verb-tenses', 'intermediate', 'knowledge', 'en', 'perfect-aspect', 'I ___ in this neighbourhood for five years, and I still live here.', '我在这个社区住了五年，而且现在仍然住在这里。', '[{"id":"a","learning_text":"lived","translation_text":"住过（过去式）"},{"id":"b","learning_text":"have lived","translation_text":"已经住了"},{"id":"c","learning_text":"am living","translation_text":"正在居住"},{"id":"d","learning_text":"had lived","translation_text":"此前住过"}]'::jsonb, 'b', 'The present perfect connects a situation that began in the past with the present; the sentence says it continues now.', '现在完成时把过去开始并延续到现在的情况联系起来；句子说明目前仍住在这里。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-024', 1, 'en', 'zh', 'i-perfect', 'verb-tenses', 'intermediate', 'knowledge', 'en', 'perfect-aspect', 'Choose the correct sentence for a completed action at a finished time yesterday.', '选择描述昨天某个已结束时间内完成动作的正确句子。', '[{"id":"a","learning_text":"I have seen her yesterday.","translation_text":"我昨天见过她。"},{"id":"b","learning_text":"I had seen her yesterday.","translation_text":"我昨天之前见过她。"},{"id":"c","learning_text":"I saw her yesterday.","translation_text":"我昨天见到了她。"},{"id":"d","learning_text":"I am seeing her yesterday.","translation_text":"我昨天正在见她。"}]'::jsonb, 'c', '“Yesterday” is a finished past time, so the past simple “saw” is used.', '“Yesterday”表示已经结束的过去时间，因此使用一般过去时“saw”。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-025', 1, 'en', 'zh', 'i-perfect', 'verb-tenses', 'intermediate', 'knowledge', 'en', 'perfect-aspect', 'By the time we arrived at the cinema, the film ___.', '我们到达电影院时，电影已经开始了。', '[{"id":"a","learning_text":"has started","translation_text":"已经开始（现在完成时）"},{"id":"b","learning_text":"was starting","translation_text":"当时正在开始"},{"id":"c","learning_text":"had started","translation_text":"此前已经开始"},{"id":"d","learning_text":"starts","translation_text":"开始（一般现在时）"}]'::jsonb, 'c', 'The film started before the later past event of our arrival, so the past perfect is used.', '电影开始发生在我们到达之前，因此使用过去完成时。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-026', 1, 'en', 'zh', 'i-perfect', 'verb-tenses', 'intermediate', 'knowledge', 'en', 'perfect-aspect', 'Lena ___ for three hours, and she is still studying now.', 'Lena已经学习了三个小时，而且现在仍在学习。', '[{"id":"a","learning_text":"studied","translation_text":"学习了（过去式）"},{"id":"b","learning_text":"has been studying","translation_text":"一直在学习"},{"id":"c","learning_text":"had studied","translation_text":"此前学习过"},{"id":"d","learning_text":"studies","translation_text":"学习（一般现在时）"}]'::jsonb, 'b', 'The present perfect continuous emphasizes an activity that began earlier and is still continuing.', '现在完成进行时强调一项较早开始并持续到现在的活动。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-027', 1, 'en', 'zh', 'i-perfect', 'verb-tenses', 'intermediate', 'knowledge', 'en', 'perfect-aspect', 'Choose the correct word: I have worked at this school ___ 2020.', '选择正确的词：我从2020年起就在这所学校工作。', '[{"id":"a","learning_text":"for","translation_text":"持续了"},{"id":"b","learning_text":"during","translation_text":"在……期间"},{"id":"c","learning_text":"since","translation_text":"自从"},{"id":"d","learning_text":"until","translation_text":"直到"}]'::jsonb, 'c', '“Since” introduces the starting point of a period that continues to the present.', '“Since”引出持续到现在的一段时间的起点。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-028', 1, 'en', 'zh', 'i-perfect', 'verb-tenses', 'intermediate', 'knowledge', 'en', 'perfect-aspect', 'Choose the negative present-perfect sentence using “yet” to show that the report is still unfinished.', '选择在现在完成时否定句中正确使用“yet”的句子。', '[{"id":"a","learning_text":"I haven''t finished the report yet.","translation_text":"我还没有完成报告。"},{"id":"b","learning_text":"I haven''t yet sent the report.","translation_text":"我还没有发送报告。"},{"id":"c","learning_text":"I don''t have to finish the report yet.","translation_text":"我现在还不必完成报告。"},{"id":"d","learning_text":"I hadn''t finished the report by noon.","translation_text":"到中午时我还没有完成报告。"}]'::jsonb, 'a', 'In a negative present perfect statement, “yet” commonly appears at the end after the past participle.', '在现在完成时否定句中，“yet”通常放在过去分词之后的句末。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-029', 1, 'en', 'zh', 'i-perfect', 'verb-tenses', 'intermediate', 'knowledge', 'en', 'perfect-aspect', 'Choose the present-perfect sentence showing that all the guests left before now.', '选择正确的句子，表示客人已经在现在之前离开。', '[{"id":"a","learning_text":"The guests have already left.","translation_text":"客人已经离开了。"},{"id":"b","learning_text":"The guest has already left.","translation_text":"那位客人已经离开了。"},{"id":"c","learning_text":"The guests have already arrived.","translation_text":"客人已经到了。"},{"id":"d","learning_text":"The guests were already leaving.","translation_text":"客人当时已经在离开了。"}]'::jsonb, 'a', 'The plural subject “guests” takes “have,” followed by the past participle “left.”', '复数主语“guests”使用“have”，后接过去分词“left”。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-030', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'knowledge', 'en', 'word-formation-and-confusable-forms', 'Choose the noun form of the verb “decide” to complete the sentence: Her ___ surprised everyone.', '选择动词“decide”的名词形式完成句子：她的决定让所有人都感到惊讶。', '[{"id":"a","learning_text":"decisive","translation_text":"果断的"},{"id":"b","learning_text":"decision","translation_text":"决定"},{"id":"c","learning_text":"deciding","translation_text":"正在决定"},{"id":"d","learning_text":"decided","translation_text":"已决定的"}]'::jsonb, 'b', '“Decision” is the noun form of “decide.”', '“Decision”是动词“decide”的名词形式。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-031', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'knowledge', 'en', 'word-formation-and-confusable-forms', 'Choose the adjective form of “rely”: We need a ___ source of information.', '选择“rely”的形容词形式：我们需要一个可靠的信息来源。', '[{"id":"a","learning_text":"reliance","translation_text":"依赖"},{"id":"b","learning_text":"reliably","translation_text":"可靠地"},{"id":"c","learning_text":"reliable","translation_text":"可靠的"},{"id":"d","learning_text":"reliability","translation_text":"可靠性"}]'::jsonb, 'c', '“Reliable” is the adjective describing something or someone that can be relied on.', '“Reliable”是形容词，形容某事物或某人值得信赖。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-032', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'knowledge', 'en', 'word-formation-and-confusable-forms', 'Choose the correct adjective: The project was ___ because it met all its goals.', '选择正确的形容词：这个项目很成功，因为它达成了所有目标。', '[{"id":"a","learning_text":"success","translation_text":"成功（名词）"},{"id":"b","learning_text":"successfully","translation_text":"成功地"},{"id":"c","learning_text":"successful","translation_text":"成功的"},{"id":"d","learning_text":"succeed","translation_text":"成功（动词）"}]'::jsonb, 'c', '“Successful” is the adjective form used to describe the project.', '“Successful”是用于描述项目的形容词形式。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-033', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'knowledge', 'en', 'word-formation-and-confusable-forms', 'The artist is known for her original ideas and great ___.', '这位艺术家以独特的想法和丰富的创造力而闻名。', '[{"id":"a","learning_text":"creative","translation_text":"有创造力的"},{"id":"b","learning_text":"creation","translation_text":"创作/作品"},{"id":"c","learning_text":"creatively","translation_text":"有创造性地"},{"id":"d","learning_text":"creativity","translation_text":"创造力"}]'::jsonb, 'd', '“Creativity” is the noun for the ability to produce original ideas.', '“Creativity”是名词，表示产生原创想法的能力。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-034', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'knowledge', 'en', 'word-formation-and-confusable-forms', 'The speaker tried to ___ the audience to support the proposal.', '演讲者试图说服观众支持这项提议。', '[{"id":"a","learning_text":"persuasion","translation_text":"说服（名词）"},{"id":"b","learning_text":"persuasive","translation_text":"有说服力的"},{"id":"c","learning_text":"persuade","translation_text":"说服"},{"id":"d","learning_text":"persuasively","translation_text":"有说服力地"}]'::jsonb, 'c', 'After “tried to,” the base verb “persuade” is required.', '“Tried to”后面需要接动词原形“persuade”。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-035', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'knowledge', 'en', 'word-formation-and-confusable-forms', 'The road becomes ___ at night, so drivers should slow down.', '这条路在夜间会变得危险，因此驾驶员应该减速。', '[{"id":"a","learning_text":"danger","translation_text":"危险（名词）"},{"id":"b","learning_text":"dangerous","translation_text":"危险的"},{"id":"c","learning_text":"dangerously","translation_text":"危险地"},{"id":"d","learning_text":"endanger","translation_text":"危及"}]'::jsonb, 'b', '“Dangerous” is the adjective describing the road.', '“Dangerous”是用于描述道路的形容词。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-036', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'knowledge', 'en', 'word-formation-and-confusable-forms', 'Choose the noun form of “accurate”: The ___ of the measurements is important.', '选择“accurate”的名词形式：测量结果的准确性很重要。', '[{"id":"a","learning_text":"accurately","translation_text":"准确地"},{"id":"b","learning_text":"accuracy","translation_text":"准确性"},{"id":"c","learning_text":"accurate","translation_text":"准确的"},{"id":"d","learning_text":"inaccurate","translation_text":"不准确的"}]'::jsonb, 'b', '“Accuracy” is the noun form of the adjective “accurate.”', '“Accuracy”是形容词“accurate”的名词形式。', 'approved', pg_catalog.now()),
  ('quiz-advanced-001', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'Which verb most appropriately hedges this claim? “The initial results ___ that the new process may reduce delays.”', '哪个动词最适合用来谨慎表达这一主张？“初步结果___新流程可能减少延误。”', '[{"id":"a","learning_text":"prove","translation_text":"证明"},{"id":"b","learning_text":"suggest","translation_text":"表明/暗示"},{"id":"c","learning_text":"guarantee","translation_text":"保证"},{"id":"d","learning_text":"establish","translation_text":"确立/证实"}]'::jsonb, 'b', '“Suggest” presents a possible interpretation without claiming definitive proof.', '“Suggest”表达一种可能的解释，而不是声称已经得到确凿证明。', 'approved', pg_catalog.now()),
  ('quiz-advanced-002', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'Complete the cautious statement: The difference may be ___ to variation in the sample.', '补全谨慎表达：这种差异可能___样本中的变化。', '[{"id":"a","learning_text":"certainly due","translation_text":"肯定由于"},{"id":"b","learning_text":"entirely caused","translation_text":"完全由……造成"},{"id":"c","learning_text":"partly attributable","translation_text":"部分归因于"},{"id":"d","learning_text":"undeniably explained","translation_text":"无可否认地解释"}]'::jsonb, 'c', '“Partly attributable to” signals a possible contributing factor without claiming it is the only cause.', '“Partly attributable to”表示某因素可能是部分原因，但不声称它是唯一原因。', 'approved', pg_catalog.now()),
  ('quiz-advanced-003', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'Given the limited sample size, the findings should be interpreted ___.', '鉴于样本量有限，应当___地解读这些发现。', '[{"id":"a","learning_text":"universally","translation_text":"普遍地"},{"id":"b","learning_text":"cautiously","translation_text":"谨慎地"},{"id":"c","learning_text":"conclusively","translation_text":"决定性地"},{"id":"d","learning_text":"literally","translation_text":"按字面地"}]'::jsonb, 'b', '“Cautiously” appropriately signals that limited evidence should not support overconfident conclusions.', '“Cautiously”恰当地表示证据有限，不应据此作出过度肯定的结论。', 'approved', pg_catalog.now()),
  ('quiz-advanced-004', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'The observed pattern is ___ with previous studies, although the methods differ.', '观察到的模式与以往研究___，尽管研究方法有所不同。', '[{"id":"a","learning_text":"identical","translation_text":"完全相同"},{"id":"b","learning_text":"conclusive","translation_text":"结论性的"},{"id":"c","learning_text":"consistent","translation_text":"一致/相符"},{"id":"d","learning_text":"guaranteed","translation_text":"有保证的"}]'::jsonb, 'c', '“Consistent with” means the pattern agrees with earlier findings without claiming the studies are identical.', '“Consistent with”表示该模式与先前研究结果相符，但不表示两项研究完全相同。', 'approved', pg_catalog.now()),
  ('quiz-advanced-005', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'The increase in costs may ___ from changes in supplier prices.', '成本上升可能___供应商价格的变化。', '[{"id":"a","learning_text":"stem","translation_text":"源于"},{"id":"b","learning_text":"prove","translation_text":"证明"},{"id":"c","learning_text":"conclude","translation_text":"得出结论"},{"id":"d","learning_text":"ensure","translation_text":"确保"}]'::jsonb, 'a', '“Stem from” means to originate from or be caused by something.', '“Stem from”表示源自某事或由某事引起。', 'approved', pg_catalog.now()),
  ('quiz-advanced-006', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'Without a larger comparison group, it would be ___ to claim that the treatment is more effective.', '如果没有更大的对照组，就断言该治疗方法更有效还为时___。', '[{"id":"a","learning_text":"inevitable","translation_text":"不可避免"},{"id":"b","learning_text":"premature","translation_text":"过早"},{"id":"c","learning_text":"conclusive","translation_text":"确定"},{"id":"d","learning_text":"universal","translation_text":"普遍"}]'::jsonb, 'b', '“Premature” indicates that the available evidence is not yet sufficient for the conclusion.', '“Premature”表示现有证据尚不足以支持这一结论，现在下结论为时过早。', 'approved', pg_catalog.now()),
  ('quiz-advanced-007', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'Because the estimates are based on a small sample, they remain ___.', '由于这些估算基于较小的样本，因此仍然具有___性。', '[{"id":"a","learning_text":"absolute","translation_text":"绝对"},{"id":"b","learning_text":"tentative","translation_text":"暂定/初步"},{"id":"c","learning_text":"final","translation_text":"最终"},{"id":"d","learning_text":"certain","translation_text":"确定"}]'::jsonb, 'b', '“Tentative” describes a conclusion that is provisional and may change with further evidence.', '“Tentative”表示暂时性的结论，可能会随着更多证据而改变。', 'approved', pg_catalog.now()),
  ('quiz-advanced-008', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'The revised schedule is likely to have a ___ effect on overall costs rather than transform the budget.', '修订后的时间表可能只会对总成本产生___影响，而不会彻底改变预算。', '[{"id":"a","learning_text":"modest","translation_text":"有限/适度的"},{"id":"b","learning_text":"guaranteed","translation_text":"有保证的"},{"id":"c","learning_text":"universal","translation_text":"普遍的"},{"id":"d","learning_text":"absolute","translation_text":"绝对的"}]'::jsonb, 'a', '“Modest effect” signals a limited degree of impact rather than a sweeping or certain outcome.', '“Modest effect”表示影响程度有限，而不是全面或必然的结果。', 'approved', pg_catalog.now()),
  ('quiz-advanced-009', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'The available evidence ___ suggests a link between sleep and concentration, but further research is needed.', '现有证据___地表明睡眠与注意力之间可能存在联系，但仍需要进一步研究。', '[{"id":"a","learning_text":"indisputably","translation_text":"无可争议地"},{"id":"b","learning_text":"permanently","translation_text":"永久地"},{"id":"c","learning_text":"tentatively","translation_text":"初步地/暂时地"},{"id":"d","learning_text":"conclusively","translation_text":"决定性地"}]'::jsonb, 'c', '“Tentatively” communicates that the evidence suggests a link but does not establish it conclusively.', '“Tentatively”表示证据初步显示存在联系，但尚未作出决定性证明。', 'approved', pg_catalog.now()),
  ('quiz-advanced-010', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'knowledge', 'en', 'qualified-academic-claims', 'The survey results ___ the possibility that flexible hours improve staff retention.', '调查结果___了灵活工时可能提高员工留任率这一可能性。', '[{"id":"a","learning_text":"settle","translation_text":"解决/确定"},{"id":"b","learning_text":"raise","translation_text":"提出/引起"},{"id":"c","learning_text":"guarantee","translation_text":"保证"},{"id":"d","learning_text":"dismiss","translation_text":"排除/否定"}]'::jsonb, 'b', '“Raise the possibility” introduces a plausible explanation for consideration without confirming it.', '“Raise the possibility”表示提出一种值得考虑的可能性，而不是确认其为事实。', 'approved', pg_catalog.now()),
  ('quiz-advanced-011', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Complete the sentence: Not until the final report was published ___ the scale of the problem.', '补全句子：直到最终报告发布后，公众才___问题的严重程度。', '[{"id":"a","learning_text":"the public understood","translation_text":"公众理解了"},{"id":"b","learning_text":"did the public understand","translation_text":"公众才理解"},{"id":"c","learning_text":"the public did understood","translation_text":"公众确实理解"},{"id":"d","learning_text":"understood the public","translation_text":"理解了公众"}]'::jsonb, 'b', 'A negative fronted phrase such as “Not until” triggers subject–auxiliary inversion in the main clause: “did the public understand.”', '“Not until”等否定意义短语置于句首时，主句需要主谓倒装，使用“did the public understand”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-012', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Choose the correct inversion: Rarely ___ such a detailed analysis of the issue.', '选择正确的倒装形式：我们很少看到对这个问题如此详细的分析。', '[{"id":"a","learning_text":"we have seen","translation_text":"我们已经看到"},{"id":"b","learning_text":"have we seen","translation_text":"我们曾看到"},{"id":"c","learning_text":"did we saw","translation_text":"我们看到了"},{"id":"d","learning_text":"we saw","translation_text":"我们看到"}]'::jsonb, 'b', '“Rarely” at the beginning of a clause requires subject–auxiliary inversion: “have we seen.”', '“Rarely”置于句首时需要主谓倒装，因此使用“have we seen”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-013', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Complete the sentence: Only after the data had been checked ___ the team release the report.', '补全句子：只有在数据核查完毕后，团队才___发布报告。', '[{"id":"a","learning_text":"the team did","translation_text":"团队确实"},{"id":"b","learning_text":"had the team","translation_text":"团队已经"},{"id":"c","learning_text":"did the team","translation_text":"团队才"},{"id":"d","learning_text":"was the team","translation_text":"团队是"}]'::jsonb, 'c', 'When “Only after” introduces the fronted condition, the main clause uses inversion: “did the team release.”', '“Only after”引导的条件短语置于句首时，主句使用倒装：“did the team release”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-014', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Choose the correct formal inversion: Under no circumstances ___ confidential files with external parties.', '选择正确的正式倒装结构：在任何情况下，员工都不应与外部人员分享机密文件。', '[{"id":"a","learning_text":"staff should share","translation_text":"员工应该分享"},{"id":"b","learning_text":"should staff share","translation_text":"员工才应该分享"},{"id":"c","learning_text":"staff share","translation_text":"员工分享"},{"id":"d","learning_text":"did staff shared","translation_text":"员工曾分享"}]'::jsonb, 'b', '“Under no circumstances” is a negative fronted phrase and requires inversion: “should staff share.”', '“Under no circumstances”是否定意义的句首短语，需要倒装，使用“should staff share”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-015', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Complete the third conditional inversion: Had I known about the delay, I ___ an earlier train.', '补全第三条件句倒装结构：如果我当时知道会延误，我就会乘坐更早的一班火车。', '[{"id":"a","learning_text":"would take","translation_text":"会乘坐"},{"id":"b","learning_text":"will have taken","translation_text":"将已经乘坐"},{"id":"c","learning_text":"would have taken","translation_text":"本来会乘坐"},{"id":"d","learning_text":"had taken","translation_text":"已经乘坐"}]'::jsonb, 'c', '“Had I known” replaces “If I had known”; the unreal past result takes “would have” plus a past participle.', '“Had I known”相当于“If I had known”；与过去事实相反的结果使用“would have”加过去分词。', 'approved', pg_catalog.now()),
  ('quiz-advanced-016', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Choose the correct completion: No sooner ___ than the lights went out.', '选择正确的补全：我们刚坐下，灯就熄灭了。', '[{"id":"a","learning_text":"we had sat down","translation_text":"我们已经坐下"},{"id":"b","learning_text":"did we sat down","translation_text":"我们坐下了"},{"id":"c","learning_text":"had we sat down","translation_text":"我们刚坐下"},{"id":"d","learning_text":"we sat down","translation_text":"我们坐下"}]'::jsonb, 'c', 'The structure “No sooner had + subject + past participle + than” describes one event immediately followed by another.', '结构“No sooner had + 主语 + 过去分词 + than”表示一件事刚发生，另一件事就紧接着发生。', 'approved', pg_catalog.now()),
  ('quiz-advanced-017', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Complete the sentence: Little ___ that the decision would reshape the industry.', '补全句子：他们当时完全没有想到，这项决定会重塑整个行业。', '[{"id":"a","learning_text":"they knew","translation_text":"他们知道"},{"id":"b","learning_text":"did they know","translation_text":"他们当时知道"},{"id":"c","learning_text":"they did knew","translation_text":"他们确实知道"},{"id":"d","learning_text":"had they knew","translation_text":"他们此前知道"}]'::jsonb, 'b', '“Little” meaning “not at all” at the beginning of a clause triggers inversion: “did they know.”', '“Little”表示“完全没有”并置于句首时会触发倒装，使用“did they know”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-018', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Choose the correct structure: Not only ___ the budget, but it also reduced delays.', '选择正确结构：该计划不仅削减了预算，还减少了延误。', '[{"id":"a","learning_text":"the plan cut","translation_text":"计划削减"},{"id":"b","learning_text":"did the plan cut","translation_text":"计划不仅削减"},{"id":"c","learning_text":"had the plan cutted","translation_text":"计划已经削减"},{"id":"d","learning_text":"the plan did cutted","translation_text":"计划确实削减"}]'::jsonb, 'b', 'When “Not only” begins the clause, the auxiliary precedes the subject: “did the plan cut.”', '“Not only”置于分句开头时，助动词要放在主语之前，使用“did the plan cut”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-019', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Choose the passive inversion form that correctly completes: “At no point ___ of the change to the contract.”', '选择正确的补全：在任何时候，客户都没有被告知合同变更。', '[{"id":"a","learning_text":"the client received notice","translation_text":"客户收到了变更通知。"},{"id":"b","learning_text":"did the client inform","translation_text":"客户告知了变更事项。"},{"id":"c","learning_text":"was the client informed","translation_text":"客户被告知了合同变更。"},{"id":"d","learning_text":"the client did inform","translation_text":"客户确实通知了相关人员。"}]'::jsonb, 'c', 'The negative phrase “At no point” triggers inversion; the passive form is “was the client informed.”', '否定短语“At no point”触发倒装；此处被动语态应为“was the client informed”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-020', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'formal-inversion', 'Complete the emphatic structure: So unexpected ___ that the committee requested a second review.', '补全强调倒装结构：结果如此出乎意料，以至于委员会要求进行第二次审查。', '[{"id":"a","learning_text":"the result was","translation_text":"结果是"},{"id":"b","learning_text":"did the result","translation_text":"结果做了"},{"id":"c","learning_text":"was the result","translation_text":"结果竟然如此"},{"id":"d","learning_text":"had the result","translation_text":"结果已经"}]'::jsonb, 'c', 'The “So + adjective” structure at the beginning triggers inversion: “So unexpected was the result that...”', '“So + 形容词”结构置于句首时需要倒装：“So unexpected was the result that...”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-021', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'Choose the correct mixed conditional: If I had accepted the scholarship, I ___ at university now.', '选择正确的混合条件句：如果我当时接受了奖学金，我现在就会在大学学习。', '[{"id":"a","learning_text":"would have studied","translation_text":"本来会学习"},{"id":"b","learning_text":"will be studying","translation_text":"将会学习"},{"id":"c","learning_text":"would be studying","translation_text":"现在会正在学习"},{"id":"d","learning_text":"had studied","translation_text":"此前学习过"}]'::jsonb, 'c', 'The past perfect describes the unreal past choice; “would be studying” expresses its present result.', '过去完成时描述与过去事实相反的选择；“would be studying”表达该选择在现在产生的结果。', 'approved', pg_catalog.now()),
  ('quiz-advanced-022', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'If she were more organised, she ___ the deadline yesterday.', '如果她更有条理，她昨天就不会错过截止日期。', '[{"id":"a","learning_text":"would not miss","translation_text":"不会错过"},{"id":"b","learning_text":"would not have missed","translation_text":"本来不会错过"},{"id":"c","learning_text":"will not have missed","translation_text":"将不会错过"},{"id":"d","learning_text":"had not missed","translation_text":"此前没有错过"}]'::jsonb, 'b', 'The present unreal condition uses “were”; the unreal past result uses “would not have missed.”', '现在的非真实条件使用“were”；与过去事实相反的结果使用“would not have missed”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-023', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'If they had not moved abroad, they ___ here now.', '如果他们当时没有移居国外，他们现在就仍然住在这里。', '[{"id":"a","learning_text":"would still be living","translation_text":"现在仍会住着"},{"id":"b","learning_text":"will still live","translation_text":"将仍然居住"},{"id":"c","learning_text":"would have still lived","translation_text":"本来仍住过"},{"id":"d","learning_text":"had still lived","translation_text":"此前仍住过"}]'::jsonb, 'a', 'The past perfect condition refers to an unreal past event, while “would still be living” gives the imagined present result.', '过去完成时条件指与过去事实相反的事件；“would still be living”描述假设中的现在结果。', 'approved', pg_catalog.now()),
  ('quiz-advanced-024', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'If he had taken the medicine, he ___ better now.', '如果他当时吃了药，他现在就会感觉好一些。', '[{"id":"a","learning_text":"will feel","translation_text":"将会感觉"},{"id":"b","learning_text":"would have felt","translation_text":"本来会感觉"},{"id":"c","learning_text":"would feel","translation_text":"现在会感觉"},{"id":"d","learning_text":"had felt","translation_text":"此前感觉"}]'::jsonb, 'c', 'The unreal past condition leads to a present result, so the main clause uses “would feel.”', '与过去事实相反的条件导致现在的结果，因此主句使用“would feel”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-025', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'If I were not afraid of heights, I ___ the climb last weekend.', '如果我不恐高，我上周末就会参加那次攀登。', '[{"id":"a","learning_text":"would join","translation_text":"会参加"},{"id":"b","learning_text":"will have joined","translation_text":"将已经参加"},{"id":"c","learning_text":"would have joined","translation_text":"本来会参加"},{"id":"d","learning_text":"had joined","translation_text":"此前参加"}]'::jsonb, 'c', 'The present unreal condition “were not afraid” explains a different possible past result: “would have joined.”', '现在的非真实条件“were not afraid”解释了一个不同的过去结果，因此使用“would have joined”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-026', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'If the company had invested earlier, it ___ a larger market share today.', '如果公司当时更早投资，它今天就会拥有更大的市场份额。', '[{"id":"a","learning_text":"will have","translation_text":"将拥有"},{"id":"b","learning_text":"would have","translation_text":"现在会拥有"},{"id":"c","learning_text":"would have had","translation_text":"本来会拥有过"},{"id":"d","learning_text":"had had","translation_text":"此前拥有过"}]'::jsonb, 'b', 'The past perfect describes the unreal earlier investment; “would have” describes the present state.', '过去完成时描述未发生的早期投资；“would have”描述假设中的现在状态。', 'approved', pg_catalog.now()),
  ('quiz-advanced-027', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'If we had checked the map, we ___ lost now.', '如果我们当时查看了地图，现在就不会迷路了。', '[{"id":"a","learning_text":"would not be","translation_text":"现在就不会处于……状态"},{"id":"b","learning_text":"will not be","translation_text":"将不会"},{"id":"c","learning_text":"would not have been","translation_text":"本来不会是"},{"id":"d","learning_text":"had not been","translation_text":"此前不是"}]'::jsonb, 'a', 'The unreal past condition affects the present state, so “would not be lost now” is the correct mixed result.', '与过去事实相反的条件影响现在的状态，因此正确的混合结果是“would not be lost now”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-028', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'If she spoke French fluently, she ___ the Paris assignment last year.', '如果她法语说得流利，她去年就会接受巴黎的任务。', '[{"id":"a","learning_text":"will accept","translation_text":"将接受"},{"id":"b","learning_text":"would accept","translation_text":"会接受"},{"id":"c","learning_text":"would have accepted","translation_text":"本来会接受"},{"id":"d","learning_text":"had accepted","translation_text":"此前接受"}]'::jsonb, 'c', 'The present unreal ability condition leads to an unreal past result, expressed with “would have accepted.”', '现在的非真实能力条件导致一个未发生的过去结果，使用“would have accepted”表达。', 'approved', pg_catalog.now()),
  ('quiz-advanced-029', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'If the system were more reliable, it ___ during yesterday''s outage.', '如果系统更可靠，它昨天停电期间就不会发生故障。', '[{"id":"a","learning_text":"would not fail","translation_text":"不会发生故障"},{"id":"b","learning_text":"would not have failed","translation_text":"本来不会发生故障"},{"id":"c","learning_text":"will not have failed","translation_text":"将不会发生故障"},{"id":"d","learning_text":"had not failed","translation_text":"此前没有发生故障"}]'::jsonb, 'b', 'The present unreal condition “were more reliable” is linked to an unreal past result: “would not have failed.”', '现在的非真实条件“were more reliable”与一个未发生的过去结果相连，使用“would not have failed”。', 'approved', pg_catalog.now()),
  ('quiz-advanced-030', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'knowledge', 'en', 'mixed-conditional-meaning', 'If I had saved more money, I ___ a new laptop now.', '如果我当时存了更多钱，我现在就买得起一台新笔记本电脑。', '[{"id":"a","learning_text":"could afford","translation_text":"现在就能负担得起"},{"id":"b","learning_text":"could have afforded","translation_text":"当时本来能负担得起"},{"id":"c","learning_text":"can afford","translation_text":"现在能负担得起"},{"id":"d","learning_text":"had afforded","translation_text":"此前负担得起"}]'::jsonb, 'a', 'The past perfect describes an unreal past saving habit; “could afford” expresses the present result.', '过去完成时描述与过去事实相反的储蓄情况；“could afford”表达现在的结果。', 'approved', pg_catalog.now()),
  ('quiz-advanced-031', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'knowledge', 'en', 'figurative-idioms', 'After months of planning, the team finally got the ball rolling. What does the idiom mean?', '经过数月规划，团队终于开始行动。“get the ball rolling”是什么意思？', '[{"id":"a","learning_text":"They began the activity or process.","translation_text":"他们开始了活动或流程。"},{"id":"b","learning_text":"They ended the project permanently.","translation_text":"他们永久结束了项目。"},{"id":"c","learning_text":"They avoided making a decision.","translation_text":"他们避免作出决定。"},{"id":"d","learning_text":"They repeated the planning stage.","translation_text":"他们重复了规划阶段。"}]'::jsonb, 'a', '“Get the ball rolling” means to start an activity, process or project.', '“Get the ball rolling”表示启动一项活动、流程或项目。', 'approved', pg_catalog.now()),
  ('quiz-advanced-032', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'knowledge', 'en', 'figurative-idioms', 'The failed safety check was only the tip of the iceberg. What is implied?', '安全检查失败只是冰山一角。这句话暗示了什么？', '[{"id":"a","learning_text":"The problem is smaller than it appears.","translation_text":"问题比看起来更小。"},{"id":"b","learning_text":"The visible problem is part of a much larger one.","translation_text":"目前看到的问题只是更大问题的一部分。"},{"id":"c","learning_text":"The problem has already been solved.","translation_text":"问题已经解决。"},{"id":"d","learning_text":"The issue is caused by cold weather.","translation_text":"问题是由寒冷天气造成的。"}]'::jsonb, 'b', '“The tip of the iceberg” refers to a small visible part of a much larger hidden situation.', '“The tip of the iceberg”表示目前可见的只是更大隐藏情况的一小部分。', 'approved', pg_catalog.now()),
  ('quiz-advanced-033', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'knowledge', 'en', 'figurative-idioms', 'The contractor cut corners to finish the building sooner. What did the contractor do?', '承包商为了更快完成建筑工程而偷工减料。这表示承包商做了什么？', '[{"id":"a","learning_text":"Followed every quality procedure carefully.","translation_text":"严格遵守了所有质量程序。"},{"id":"b","learning_text":"Reduced quality or safety standards to save time or money.","translation_text":"为了节省时间或金钱而降低质量或安全标准。"},{"id":"c","learning_text":"Added extra checks to the schedule.","translation_text":"在计划中增加了额外检查。"},{"id":"d","learning_text":"Changed the design without changing the cost.","translation_text":"在不改变成本的情况下更改了设计。"}]'::jsonb, 'b', '“Cut corners” means to take shortcuts, often by sacrificing quality or proper procedure.', '“Cut corners”表示走捷径，通常意味着牺牲质量或适当程序。', 'approved', pg_catalog.now()),
  ('quiz-advanced-034', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'knowledge', 'en', 'figurative-idioms', 'Before presenting the proposal, we should make sure everyone is on the same page. What does this mean?', '在提交提案之前，我们应该确保每个人都在同一认知上。这是什么意思？', '[{"id":"a","learning_text":"Everyone has the same understanding.","translation_text":"每个人都有相同的理解。"},{"id":"b","learning_text":"Everyone works in the same office.","translation_text":"每个人都在同一间办公室工作。"},{"id":"c","learning_text":"Everyone has completed the same document.","translation_text":"每个人都完成了同一份文件。"},{"id":"d","learning_text":"Everyone agrees with every detail.","translation_text":"每个人都同意所有细节。"}]'::jsonb, 'a', '“On the same page” means sharing a common understanding; it does not necessarily mean agreeing on everything.', '“On the same page”表示拥有共同理解，但不一定意味着对所有细节都意见一致。', 'approved', pg_catalog.now()),
  ('quiz-advanced-035', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'knowledge', 'en', 'figurative-idioms', 'After the software update caused more problems, the team was back to square one. What happened?', '软件更新造成了更多问题后，团队又回到了原点。这意味着什么？', '[{"id":"a","learning_text":"The team had completed the project.","translation_text":"团队已经完成项目。"},{"id":"b","learning_text":"The team had to return to the beginning and start again.","translation_text":"团队不得不回到起点重新开始。"},{"id":"c","learning_text":"The team had found a permanent solution.","translation_text":"团队找到了永久解决方案。"},{"id":"d","learning_text":"The team had moved to a different office.","translation_text":"团队搬到了另一间办公室。"}]'::jsonb, 'b', '“Back to square one” means having to start again from the beginning.', '“Back to square one”表示不得不从头开始。', 'approved', pg_catalog.now()),
  ('quiz-advanced-036', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'knowledge', 'en', 'figurative-idioms', 'She is on the fence about accepting the promotion. What does this mean?', '她对是否接受晋升仍然犹豫不决。这是什么意思？', '[{"id":"a","learning_text":"She has already accepted it.","translation_text":"她已经接受了。"},{"id":"b","learning_text":"She is strongly opposed to it.","translation_text":"她强烈反对。"},{"id":"c","learning_text":"She has not decided whether to accept it.","translation_text":"她还没有决定是否接受。"},{"id":"d","learning_text":"She wants someone else to receive it.","translation_text":"她希望别人得到晋升。"}]'::jsonb, 'c', '“On the fence” means undecided between alternatives.', '“On the fence”表示在不同选择之间犹豫不决。', 'approved', pg_catalog.now()),
  ('quiz-advanced-037', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'knowledge', 'en', 'figurative-idioms', 'Losing the first contract seemed disappointing, but it became a blessing in disguise. What does this suggest?', '失去第一份合同起初令人失望，但后来却因祸得福。这暗示了什么？', '[{"id":"a","learning_text":"The negative event eventually led to an unexpected benefit.","translation_text":"这件负面事件最终带来了意想不到的好处。"},{"id":"b","learning_text":"The event caused permanent damage.","translation_text":"这件事造成了永久损害。"},{"id":"c","learning_text":"The event was planned as a celebration.","translation_text":"这件事原本是为了庆祝而安排的。"},{"id":"d","learning_text":"The event had no effect on later events.","translation_text":"这件事对后续没有影响。"}]'::jsonb, 'a', '“A blessing in disguise” is something that seems bad at first but later produces a good result.', '“A blessing in disguise”指起初看似坏事，后来却带来好结果。', 'approved', pg_catalog.now()),
  ('quiz-advanced-038', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'knowledge', 'en', 'figurative-idioms', 'I will not join the hike today because I am feeling under the weather. What does the phrase mean?', '我今天不参加徒步，因为我感觉身体不太舒服。这个短语是什么意思？', '[{"id":"a","learning_text":"Feeling slightly ill.","translation_text":"感觉有点不舒服。"},{"id":"b","learning_text":"Feeling unusually energetic.","translation_text":"感觉精力异常充沛。"},{"id":"c","learning_text":"Being caught in heavy rain.","translation_text":"遇到大雨。"},{"id":"d","learning_text":"Feeling confused about directions.","translation_text":"对方向感到困惑。"}]'::jsonb, 'a', '“Under the weather” is an informal expression meaning slightly ill or unwell.', '“Under the weather”是非正式表达，表示身体有些不舒服。', 'approved', pg_catalog.now()),
  ('quiz-advanced-039', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'knowledge', 'en', 'figurative-idioms', 'The new safety measures may seem expensive now, but they will save money in the long run. What does “in the long run” mean?', '新的安全措施现在看起来可能很昂贵，但从长远来看会节省成本。“in the long run”是什么意思？', '[{"id":"a","learning_text":"Immediately after the purchase.","translation_text":"购买后立即。"},{"id":"b","learning_text":"Over an extended period of time.","translation_text":"经过较长一段时间后。"},{"id":"c","learning_text":"Only during the first week.","translation_text":"只在第一周。"},{"id":"d","learning_text":"Before the project begins.","translation_text":"项目开始之前。"}]'::jsonb, 'b', '“In the long run” refers to the eventual result over a long period of time.', '“In the long run”表示经过较长时间后最终产生的结果。', 'approved', pg_catalog.now()),
  ('quiz-advanced-040', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'knowledge', 'en', 'precise-word-choice', 'Choose the correct word: The company is looking for a more ___ way to package its products, using less material.', '选择正确的词：公司正在寻找一种更___的产品包装方式，以减少材料使用。', '[{"id":"a","learning_text":"economic","translation_text":"经济方面的"},{"id":"b","learning_text":"economical","translation_text":"节省成本/材料的"},{"id":"c","learning_text":"economy","translation_text":"经济/节约"},{"id":"d","learning_text":"economics","translation_text":"经济学"}]'::jsonb, 'b', '“Economical” means using resources, money or materials efficiently; “economic” usually relates to the economy.', '“Economical”表示有效节省资源、金钱或材料；“economic”通常与经济体系有关。', 'approved', pg_catalog.now()),
  ('quiz-advanced-041', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'knowledge', 'en', 'precise-word-choice', 'Choose the correct word: The signing of the peace agreement was a ___ moment in the country''s history.', '选择正确的词：和平协议的签署是该国历史上一个___的时刻。', '[{"id":"a","learning_text":"historical","translation_text":"与历史有关的"},{"id":"b","learning_text":"historic","translation_text":"具有历史意义的"},{"id":"c","learning_text":"historically","translation_text":"从历史角度"},{"id":"d","learning_text":"historian","translation_text":"历史学家"}]'::jsonb, 'b', '“Historic” describes an event that is important or significant in history; “historical” means related to the past or the study of history.', '“Historic”形容具有重大历史意义的事件；“historical”表示与过去或历史研究有关。', 'approved', pg_catalog.now()),
  ('quiz-advanced-042', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'knowledge', 'en', 'precise-word-choice', 'Choose the correct word: The new attendance rule may ___ how employees plan their shifts.', '选择正确的词：新的出勤规定可能会___员工安排轮班的方式。', '[{"id":"a","learning_text":"effect","translation_text":"影响（名词）"},{"id":"b","learning_text":"affect","translation_text":"影响（动词）"},{"id":"c","learning_text":"effective","translation_text":"有效的"},{"id":"d","learning_text":"affection","translation_text":"喜爱"}]'::jsonb, 'b', '“Affect” is the verb meaning to influence; “effect” is most commonly used as a noun meaning a result.', '“Affect”是表示影响的动词；“effect”最常用作名词，表示结果。', 'approved', pg_catalog.now()),
  ('quiz-advanced-043', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'knowledge', 'en', 'precise-word-choice', 'Choose the correct verb: Please ___ a complete backup of all files before the server is replaced.', '选择正确的动词：更换服务器前，请确保所有文件都已完整备份。', '[{"id":"a","learning_text":"assure","translation_text":"向某人保证"},{"id":"b","learning_text":"ensure","translation_text":"确保"},{"id":"c","learning_text":"insure","translation_text":"为……投保"},{"id":"d","learning_text":"reassure","translation_text":"使安心"}]'::jsonb, 'b', '“Ensure” means to make certain that something happens or is true; “assure” usually means to tell someone confidently.', '“Ensure”表示确保某事发生或属实；“assure”通常表示向某人作出保证。', 'approved', pg_catalog.now()),
  ('quiz-advanced-044', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'knowledge', 'en', 'precise-word-choice', 'Choose the correct word: The museum director is an ___ expert on ancient ceramics.', '选择正确的词：博物馆馆长是一位研究古代陶瓷的杰出专家。', '[{"id":"a","learning_text":"imminent","translation_text":"即将发生的"},{"id":"b","learning_text":"eminent","translation_text":"杰出的"},{"id":"c","learning_text":"immanent","translation_text":"内在的"},{"id":"d","learning_text":"immediate","translation_text":"立即的"}]'::jsonb, 'b', '“Eminent” means distinguished or highly respected; “imminent” means about to happen.', '“Eminent”表示杰出或受人尊敬；“imminent”表示即将发生。', 'approved', pg_catalog.now()),
  ('quiz-advanced-045', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'knowledge', 'en', 'precise-word-choice', 'Choose the correct verb: The organisation plans to ___ a new mentoring programme next year.', '选择正确的动词：该组织计划明年___一项新的导师计划。', '[{"id":"a","learning_text":"adapt","translation_text":"调整/适应"},{"id":"b","learning_text":"adopt","translation_text":"采用"},{"id":"c","learning_text":"adept","translation_text":"熟练的"},{"id":"d","learning_text":"adapted","translation_text":"已调整"}]'::jsonb, 'b', '“Adopt” means to take up or begin using a plan or programme; “adapt” means to modify it.', '“Adopt”表示采用或开始使用计划；“adapt”表示对其进行调整。', 'approved', pg_catalog.now()),
  ('quiz-advanced-046', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'knowledge', 'en', 'precise-word-choice', 'Choose the correct word: The blue curtains ___ the warm colours in the room.', '选择正确的词：蓝色窗帘与房间里的暖色调相得益彰。', '[{"id":"a","learning_text":"compliment","translation_text":"赞美"},{"id":"b","learning_text":"complement","translation_text":"补充/衬托"},{"id":"c","learning_text":"complementary","translation_text":"互补的"},{"id":"d","learning_text":"complimentary","translation_text":"免费的/赞美的"}]'::jsonb, 'b', '“Complement” means to complete or enhance something; “compliment” means an expression of praise.', '“Complement”表示补充或衬托；“compliment”表示赞美。', 'approved', pg_catalog.now()),
  ('quiz-advanced-047', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'knowledge', 'en', 'precise-word-choice', 'Choose the correct word: The journalist was careful to be ___ when discussing the confidential negotiations.', '选择正确的词：这名记者在讨论机密谈判时谨慎而审慎。', '[{"id":"a","learning_text":"discrete","translation_text":"分离的/不连续的"},{"id":"b","learning_text":"discreet","translation_text":"谨慎的/审慎的"},{"id":"c","learning_text":"discretion","translation_text":"判断力/谨慎"},{"id":"d","learning_text":"discreetly","translation_text":"谨慎地"}]'::jsonb, 'b', '“Discreet” means careful and tactful, especially to avoid revealing private information; “discrete” means separate or distinct.', '“Discreet”表示谨慎且得体，尤其指避免泄露私人信息；“discrete”表示分离或彼此独立。', 'approved', pg_catalog.now()),
  ('quiz-advanced-048', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'knowledge', 'en', 'precise-word-choice', 'Choose the correct word: The witness gave a ___ account that matched the available evidence.', '选择正确的词：证人的陈述可信，并且与现有证据相符。', '[{"id":"a","learning_text":"credulous","translation_text":"轻信的"},{"id":"b","learning_text":"credible","translation_text":"可信的"},{"id":"c","learning_text":"credibility","translation_text":"可信度"},{"id":"d","learning_text":"incredible","translation_text":"难以置信的"}]'::jsonb, 'b', '“Credible” means believable or worthy of trust; “credulous” describes someone too ready to believe things.', '“Credible”表示可信或值得信赖；“credulous”形容一个人过于轻信。', 'approved', pg_catalog.now()),
  ('quiz-beginner-zh-001', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'chinese_translation', 'zh', 'everyday-collocations', 'Choose the most accurate Simplified Chinese translation of: “I usually have breakfast at home.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"I usually eat breakfast at home.","translation_text":"我通常在家吃早餐。"},{"id":"b","learning_text":"I ate breakfast at home yesterday.","translation_text":"我昨天在家吃了早餐。"},{"id":"c","learning_text":"I usually cook dinner at home.","translation_text":"我通常在家做晚餐。"},{"id":"d","learning_text":"I usually eat lunch at home.","translation_text":"我通常在家吃午餐。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-beginner-zh-002', 1, 'en', 'zh', 'b-present', 'verb-tenses', 'beginner', 'chinese_translation', 'zh', 'present-simple-routines', 'Choose the most accurate Simplified Chinese translation of: “She goes to work by bus every day.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"She travels to work by bus each day.","translation_text":"她每天坐公交车去上班。"},{"id":"b","learning_text":"She travelled to work by bus yesterday.","translation_text":"她昨天坐公交车去上班。"},{"id":"c","learning_text":"She takes a bus home from work every day.","translation_text":"她每天坐公交车下班回家。"},{"id":"d","learning_text":"She drives to work every day.","translation_text":"她每天开车去上班。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-beginner-zh-003', 1, 'en', 'zh', 'b-articles', 'nouns-and-articles', 'beginner', 'chinese_translation', 'zh', 'article-use-and-sound', 'Choose the most accurate Simplified Chinese translation of: “There is a book on the table.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"A book is under the table.","translation_text":"桌子下面有一本书。"},{"id":"b","learning_text":"There are several books on the table.","translation_text":"桌子上有几本书。"},{"id":"c","learning_text":"One book is on the table.","translation_text":"桌子上有一本书。"},{"id":"d","learning_text":"A book is beside the table.","translation_text":"桌子旁边有一本书。"}]'::jsonb, 'c', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-001', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'chinese_translation', 'zh', 'natural-collocations', 'Choose the most accurate Simplified Chinese translation of: “After considering the options, she made a decision.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"After weighing the choices, she decided.","translation_text":"她考虑了各种选择后，做出了决定。"},{"id":"b","learning_text":"After weighing the choices, she changed the plan.","translation_text":"她考虑了各种选择后，改变了计划。"},{"id":"c","learning_text":"After weighing the choices, she postponed the meeting.","translation_text":"她考虑了各种选择后，推迟了会议。"},{"id":"d","learning_text":"After weighing the choices, she raised a question.","translation_text":"她考虑了各种选择后，提出了一个问题。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-002', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'chinese_translation', 'zh', 'conditional-meaning-and-forms', 'Choose the most accurate Simplified Chinese translation of: “If I had more time, I would sign up for the course.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"If I had more time, I would already have finished the course.","translation_text":"如果我有更多时间，我就已经完成这门课程了。"},{"id":"b","learning_text":"If I had more time, I would enrol in the course.","translation_text":"如果我有更多时间，我就会报名参加这门课程。"},{"id":"c","learning_text":"Because I have more time, I have enrolled in the course.","translation_text":"因为我有更多时间，所以我已经报名参加这门课程了。"},{"id":"d","learning_text":"If I had less time, I would teach the course.","translation_text":"如果我有更少的时间，我就会教授这门课程。"}]'::jsonb, 'b', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-003', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'chinese_translation', 'zh', 'phrasal-verbs-in-context', 'Choose the most accurate Simplified Chinese translation of: “The meeting was put off until Friday.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The meeting was moved forward to Monday.","translation_text":"会议提前到星期一举行。"},{"id":"b","learning_text":"The meeting was cancelled on Friday.","translation_text":"会议在星期五被取消了。"},{"id":"c","learning_text":"The meeting was postponed to Friday.","translation_text":"会议被推迟到星期五。"},{"id":"d","learning_text":"The meeting began on Friday as planned.","translation_text":"会议按计划在星期五开始了。"}]'::jsonb, 'c', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-004', 1, 'en', 'zh', 'i-perfect', 'verb-tenses', 'intermediate', 'chinese_translation', 'zh', 'perfect-aspect', 'Choose the most accurate Simplified Chinese translation of: “I have been working here for three years.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"I worked here for three years in the past.","translation_text":"我以前曾在这里工作过三年。"},{"id":"b","learning_text":"I will work here for another three years.","translation_text":"我还会在这里工作三年。"},{"id":"c","learning_text":"I worked here for three years and then left.","translation_text":"我在这里工作了三年后就离开了。"},{"id":"d","learning_text":"I started working here three years ago and still work here.","translation_text":"我已经在这里工作三年了。"}]'::jsonb, 'd', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-005', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'chinese_translation', 'zh', 'word-formation-and-confusable-forms', 'Choose the most accurate Simplified Chinese translation of: “The new policy will affect all staff.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The new rule will have an impact on every employee.","translation_text":"新政策将影响所有员工。"},{"id":"b","learning_text":"The new rule will replace every employee.","translation_text":"新政策将取代所有员工。"},{"id":"c","learning_text":"The new rule will protect every employee.","translation_text":"新政策将保护所有员工。"},{"id":"d","learning_text":"The new rule will train every employee.","translation_text":"新政策将培训所有员工。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-006', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'chinese_translation', 'zh', 'natural-collocations', 'Choose the most accurate Simplified Chinese translation of: “We must take responsibility for the mistake.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"We must blame someone else for the mistake.","translation_text":"我们必须把这个错误归咎于别人。"},{"id":"b","learning_text":"We must accept that we are accountable for the mistake.","translation_text":"我们必须为这个错误承担责任。"},{"id":"c","learning_text":"We must correct the mistake immediately.","translation_text":"我们必须立即纠正这个错误。"},{"id":"d","learning_text":"We must report the mistake to the manager.","translation_text":"我们必须向经理报告这个错误。"}]'::jsonb, 'b', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-007', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'chinese_translation', 'zh', 'conditional-meaning-and-forms', 'Choose the most accurate Simplified Chinese translation of: “Unless you hurry, you will miss the train.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"If you hurry, you will miss the train.","translation_text":"如果你快点，就会赶不上火车。"},{"id":"b","learning_text":"You will miss the train even though you hurry.","translation_text":"即使你快点，你还是会赶不上火车。"},{"id":"c","learning_text":"If you do not hurry, you will fail to catch the train.","translation_text":"除非你快点，否则就会赶不上火车。"},{"id":"d","learning_text":"You can catch the train because you are not in a hurry.","translation_text":"因为你不着急，所以你能赶上火车。"}]'::jsonb, 'c', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-008', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'chinese_translation', 'zh', 'phrasal-verbs-in-context', 'Choose the most accurate Simplified Chinese translation of: “She ran into an old friend at the station.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"She waited for an old friend at the station.","translation_text":"她在车站等一位老朋友。"},{"id":"b","learning_text":"She said goodbye to an old friend at the station.","translation_text":"她在车站向一位老朋友道别。"},{"id":"c","learning_text":"She called an old friend from the station.","translation_text":"她在车站给一位老朋友打电话。"},{"id":"d","learning_text":"She unexpectedly met an old friend at the station.","translation_text":"她在车站偶然遇见一位老朋友。"}]'::jsonb, 'd', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-009', 1, 'en', 'zh', 'i-perfect', 'verb-tenses', 'intermediate', 'chinese_translation', 'zh', 'perfect-aspect', 'Choose the most accurate Simplified Chinese translation of: “By the time we arrived, the film had started.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The film had begun before we got there.","translation_text":"我们到达时，电影已经开始了。"},{"id":"b","learning_text":"The film ended before we got there.","translation_text":"我们到达时，电影已经结束了。"},{"id":"c","learning_text":"The film was about to begin when we got there.","translation_text":"我们到达时，电影即将开始。"},{"id":"d","learning_text":"The film was delayed until after we got there.","translation_text":"电影被推迟到我们到达之后才开始。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-010', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'chinese_translation', 'zh', 'word-formation-and-confusable-forms', 'Choose the most accurate Simplified Chinese translation of: “His explanation was convincing.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"His explanation was confusing.","translation_text":"他的解释令人困惑。"},{"id":"b","learning_text":"His explanation was persuasive.","translation_text":"他的解释很有说服力。"},{"id":"c","learning_text":"His explanation was unusually brief.","translation_text":"他的解释异常简短。"},{"id":"d","learning_text":"His explanation was incomplete.","translation_text":"他的解释并不完整。"}]'::jsonb, 'b', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-011', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'chinese_translation', 'zh', 'conditional-meaning-and-forms', 'Choose the most accurate Simplified Chinese translation of: “Even if it rains, the event will continue.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"If it rains, the event will be cancelled.","translation_text":"如果下雨，活动就会取消。"},{"id":"b","learning_text":"The event will continue only if it does not rain.","translation_text":"只有不下雨，活动才会继续。"},{"id":"c","learning_text":"The event will go ahead despite the possibility of rain.","translation_text":"即使下雨，活动也会继续举行。"},{"id":"d","learning_text":"The event has already ended because it rained.","translation_text":"因为下雨，活动已经结束了。"}]'::jsonb, 'c', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-zh-012', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'chinese_translation', 'zh', 'phrasal-verbs-in-context', 'Choose the most accurate Simplified Chinese translation of: “Please look after my younger brother while I am away.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"Please take my younger brother to school while I am away.","translation_text":"我不在的时候，请送弟弟去学校。"},{"id":"b","learning_text":"Please call my younger brother while I am away.","translation_text":"我不在的时候，请给弟弟打电话。"},{"id":"c","learning_text":"Please look for my younger brother while I am away.","translation_text":"我不在的时候，请帮我寻找弟弟。"},{"id":"d","learning_text":"Please take care of my younger brother while I am away.","translation_text":"我不在的时候，请帮我照看弟弟。"}]'::jsonb, 'd', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-001', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'chinese_translation', 'zh', 'qualified-academic-claims', 'Choose the most accurate Simplified Chinese translation of: “The findings appear to suggest that the measure may be effective.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The results seem to indicate that the measure could work.","translation_text":"研究结果似乎表明，这项措施可能有效。"},{"id":"b","learning_text":"The results prove that the measure always works.","translation_text":"研究结果证明，这项措施始终有效。"},{"id":"c","learning_text":"The results show that the measure has failed completely.","translation_text":"研究结果显示，这项措施已经彻底失败。"},{"id":"d","learning_text":"The results are unrelated to whether the measure works.","translation_text":"研究结果与这项措施是否有效无关。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-002', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'chinese_translation', 'zh', 'qualified-academic-claims', 'Choose the most accurate Simplified Chinese translation of: “To some extent, the decline may be attributed to reduced demand.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The decline was entirely caused by increased demand.","translation_text":"这一下降完全是由需求增加造成的。"},{"id":"b","learning_text":"Part of the decline could be explained by lower demand.","translation_text":"在某种程度上，这一下降可能归因于需求减少。"},{"id":"c","learning_text":"The decline had no connection with demand.","translation_text":"这一下降与需求毫无关系。"},{"id":"d","learning_text":"Reduced demand was proven to be the only cause of the decline.","translation_text":"已有证据证明，需求减少是这一下降的唯一原因。"}]'::jsonb, 'b', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-003', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'chinese_translation', 'zh', 'qualified-academic-claims', 'Choose the most accurate Simplified Chinese translation of: “These figures are broadly consistent with earlier estimates.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"These figures are completely different from earlier estimates.","translation_text":"这些数据与先前的估算完全不同。"},{"id":"b","learning_text":"These figures replace all earlier estimates.","translation_text":"这些数据取代了所有先前的估算。"},{"id":"c","learning_text":"These figures generally agree with previous estimates.","translation_text":"这些数据总体上与先前的估算一致。"},{"id":"d","learning_text":"These figures cannot be compared with earlier estimates.","translation_text":"这些数据无法与先前的估算进行比较。"}]'::jsonb, 'c', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-004', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'chinese_translation', 'zh', 'qualified-academic-claims', 'Choose the most accurate Simplified Chinese translation of: “Further research would be needed to establish whether the intervention caused the improvement.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The intervention has already been proven to cause the improvement.","translation_text":"这项干预已经被证明导致了改善。"},{"id":"b","learning_text":"No further research can explain the improvement.","translation_text":"没有进一步研究能够解释这项改善。"},{"id":"c","learning_text":"The improvement occurred before the intervention was introduced.","translation_text":"这项改善发生在干预措施推出之前。"},{"id":"d","learning_text":"More study is required to determine whether the intervention caused the improvement.","translation_text":"仍需进一步研究，才能确定这项干预是否导致了改善。"}]'::jsonb, 'd', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-005', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'chinese_translation', 'zh', 'qualified-academic-claims', 'Choose the most accurate Simplified Chinese translation of: “While the evidence is compelling, it does not necessarily prove a causal relationship.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"Although the evidence is persuasive, it may not establish cause and effect.","translation_text":"虽然证据很有说服力，但并不一定能证明因果关系。"},{"id":"b","learning_text":"The evidence is weak and rules out any possible relationship.","translation_text":"证据很薄弱，并排除了任何可能的关系。"},{"id":"c","learning_text":"The evidence conclusively proves that one event caused the other.","translation_text":"证据确凿地证明一个事件导致了另一个事件。"},{"id":"d","learning_text":"The evidence is compelling because no causal relationship exists.","translation_text":"证据很有说服力，因为不存在因果关系。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-006', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'chinese_translation', 'zh', 'formal-inversion', 'Choose the most accurate Simplified Chinese translation of: “Had I known about the delay, I would have left later.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"Because I knew about the delay, I left earlier.","translation_text":"因为我知道会延误，所以我更早出发了。"},{"id":"b","learning_text":"If I had known the delay was coming, I would have departed later.","translation_text":"要是我早知道会延误，我就会晚些出发。"},{"id":"c","learning_text":"I will leave later if I hear about a delay.","translation_text":"如果我听说会延误，我就会晚些出发。"},{"id":"d","learning_text":"I left later even though I knew there would be no delay.","translation_text":"尽管我知道不会延误，我还是晚些出发了。"}]'::jsonb, 'b', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-007', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'chinese_translation', 'zh', 'formal-inversion', 'Choose the most accurate Simplified Chinese translation of: “No sooner had the announcement been made than the market reacted.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The market reacted long before the announcement was made.","translation_text":"公告发布很久以前，市场就作出了反应。"},{"id":"b","learning_text":"The announcement was delayed because the market reacted.","translation_text":"由于市场作出了反应，公告被推迟了。"},{"id":"c","learning_text":"The market responded immediately after the announcement was issued.","translation_text":"公告一发布，市场便立即作出反应。"},{"id":"d","learning_text":"The market announced that it would react at a later date.","translation_text":"市场宣布将在之后某个日期作出反应。"}]'::jsonb, 'c', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-008', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'chinese_translation', 'zh', 'formal-inversion', 'Choose the most accurate Simplified Chinese translation of: “Not only did the proposal reduce costs, but it also improved service quality.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The proposal reduced costs but made service quality worse.","translation_text":"该提案降低了成本，却使服务质量变差。"},{"id":"b","learning_text":"The proposal improved service quality without changing costs.","translation_text":"该提案提高了服务质量，但没有改变成本。"},{"id":"c","learning_text":"The proposal increased costs and reduced service quality.","translation_text":"该提案增加了成本，并降低了服务质量。"},{"id":"d","learning_text":"The proposal both lowered costs and raised service quality.","translation_text":"该提案不仅降低了成本，还提高了服务质量。"}]'::jsonb, 'd', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-009', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'chinese_translation', 'zh', 'formal-inversion', 'Choose the most accurate Simplified Chinese translation of: “At no point should confidential information be shared with outsiders.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"Confidential information must never be given to people outside the organisation.","translation_text":"在任何情况下都不应与外部人员分享机密信息。"},{"id":"b","learning_text":"Confidential information should be shared with all outsiders.","translation_text":"机密信息应该与所有外部人员分享。"},{"id":"c","learning_text":"Confidential information may be shared after a public announcement.","translation_text":"公开宣布之后，可以分享机密信息。"},{"id":"d","learning_text":"Outsiders are responsible for keeping confidential information secret.","translation_text":"外部人员有责任对机密信息保密。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-010', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'chinese_translation', 'zh', 'mixed-conditional-meaning', 'Choose the most accurate Simplified Chinese translation of: “If the team had acted sooner, it would not be facing such pressure now.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"Because the team acted early, it is under pressure now.","translation_text":"因为团队很早就采取了行动，所以现在承受着压力。"},{"id":"b","learning_text":"If the team had taken action earlier, it would not be under so much pressure now.","translation_text":"如果团队当时采取行动更早，现在就不会面临这么大的压力。"},{"id":"c","learning_text":"If the team acts sooner tomorrow, it would not have faced pressure yesterday.","translation_text":"如果团队明天更早采取行动，昨天就不会承受压力。"},{"id":"d","learning_text":"The team is under pressure because it has already solved the problem.","translation_text":"团队承受着压力，因为它已经解决了问题。"}]'::jsonb, 'b', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-011', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'chinese_translation', 'zh', 'mixed-conditional-meaning', 'Choose the most accurate Simplified Chinese translation of: “If I were more organised, I would not have missed the deadline.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"I became organised after I missed the deadline.","translation_text":"错过截止日期后，我才变得有条理。"},{"id":"b","learning_text":"If I organise my work tomorrow, I will meet the deadline.","translation_text":"如果我明天安排好工作，就能赶上截止日期。"},{"id":"c","learning_text":"If I were generally better organised, I would not have missed the deadline.","translation_text":"如果我平时更有条理，当时就不会错过截止日期。"},{"id":"d","learning_text":"I did not miss the deadline because I was disorganised.","translation_text":"我没有错过截止日期，因为我缺乏条理。"}]'::jsonb, 'c', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-012', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'chinese_translation', 'zh', 'mixed-conditional-meaning', 'Choose the most accurate Simplified Chinese translation of: “Had the data been checked, the error would not now be affecting the results.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The data is being checked now, so the results were affected in the past.","translation_text":"现在正在核查数据，因此结果过去受到了影响。"},{"id":"b","learning_text":"The data was checked, and the results are now reliable.","translation_text":"数据已经核查过，因此结果现在可靠。"},{"id":"c","learning_text":"The error has stopped affecting the results because the data was checked.","translation_text":"由于数据已经核查，错误不再影响结果。"},{"id":"d","learning_text":"If the data had been examined, the error would not still be influencing the results.","translation_text":"如果当时核查过数据，这个错误现在就不会影响结果。"}]'::jsonb, 'd', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-013', 1, 'en', 'zh', 'a-mixed-conditionals', 'advanced-grammar', 'advanced', 'chinese_translation', 'zh', 'mixed-conditional-meaning', 'Choose the most accurate Simplified Chinese translation of: “If she had accepted the offer, she would be living abroad now.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"Had she taken the offer, she would now live in another country.","translation_text":"如果她当初接受了那份工作邀请，现在就会住在国外。"},{"id":"b","learning_text":"She accepted the offer and moved abroad last year.","translation_text":"她接受了邀请，并于去年搬到了国外。"},{"id":"c","learning_text":"She will accept the offer if she moves abroad.","translation_text":"如果她搬到国外，她就会接受这份邀请。"},{"id":"d","learning_text":"She declined the offer because she already lived abroad.","translation_text":"她拒绝了邀请，因为她当时已经住在国外。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-014', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'chinese_translation', 'zh', 'figurative-idioms', 'Choose the most accurate Simplified Chinese translation of: “After months of negotiations, they finally broke the ice.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"After months of talks, they finally ended the negotiations.","translation_text":"经过数月谈判，他们终于结束了谈判。"},{"id":"b","learning_text":"After months of talks, they finally eased the tension and began communicating.","translation_text":"经过数月谈判，他们终于打破了僵局。"},{"id":"c","learning_text":"After months of talks, they finally postponed the negotiations.","translation_text":"经过数月谈判，他们终于推迟了谈判。"},{"id":"d","learning_text":"After months of talks, they finally refused to meet again.","translation_text":"经过数月谈判，他们最终拒绝再次会面。"}]'::jsonb, 'b', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-015', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'chinese_translation', 'zh', 'figurative-idioms', 'Choose the most accurate Simplified Chinese translation of: “His explanation only scratched the surface of the problem.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"His explanation solved every part of the problem.","translation_text":"他的解释解决了问题的所有方面。"},{"id":"b","learning_text":"His explanation made the problem much worse.","translation_text":"他的解释使问题变得更加严重。"},{"id":"c","learning_text":"His explanation dealt with only the most superficial part of the problem.","translation_text":"他的解释只是触及了问题的表面。"},{"id":"d","learning_text":"His explanation avoided mentioning the problem entirely.","translation_text":"他的解释完全避开了这个问题。"}]'::jsonb, 'c', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-016', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'chinese_translation', 'zh', 'figurative-idioms', 'Choose the most accurate Simplified Chinese translation of: “She decided to take the plunge and start her own business.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"She decided to delay starting her own business.","translation_text":"她决定推迟创办自己的公司。"},{"id":"b","learning_text":"She decided to close her business permanently.","translation_text":"她决定永久关闭自己的公司。"},{"id":"c","learning_text":"She decided to invest in someone else''s business.","translation_text":"她决定投资别人的公司。"},{"id":"d","learning_text":"She decided to take a bold step and establish her own company.","translation_text":"她决定鼓起勇气，创办自己的公司。"}]'::jsonb, 'd', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-017', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'chinese_translation', 'zh', 'figurative-idioms', 'Choose the most accurate Simplified Chinese translation of: “Let''s not jump to conclusions before we hear both sides.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"We should wait for both accounts before making a judgement.","translation_text":"在听取双方说法之前，我们先不要急于下结论。"},{"id":"b","learning_text":"We should decide immediately without hearing either side.","translation_text":"我们应该不听任何一方的说法就立即作出决定。"},{"id":"c","learning_text":"We should ask both sides to reach a conclusion separately.","translation_text":"我们应该让双方分别得出结论。"},{"id":"d","learning_text":"We should ignore both sides and end the discussion.","translation_text":"我们应该忽略双方的意见并结束讨论。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-018', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'chinese_translation', 'zh', 'precise-word-choice', 'Choose the most accurate Simplified Chinese translation of: “The manager''s response was tactful despite the criticism.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"The manager replied bluntly without considering anyone''s feelings.","translation_text":"经理的回应很直接，几乎没有顾及他人的感受。"},{"id":"b","learning_text":"The manager responded with care and consideration despite being criticised.","translation_text":"尽管受到批评，经理的回应仍然很得体。"},{"id":"c","learning_text":"The manager became angry and argued with the critics.","translation_text":"经理变得愤怒，并与批评者争论起来。"},{"id":"d","learning_text":"The manager refused to respond to the criticism at all.","translation_text":"经理完全没有回应这次批评。"}]'::jsonb, 'b', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-019', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'chinese_translation', 'zh', 'precise-word-choice', 'Choose the most accurate Simplified Chinese translation of: “His comments were candid rather than harsh.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"His comments were honest and deliberately insulting.","translation_text":"他的评论坦率，而且刻意带有侮辱性。"},{"id":"b","learning_text":"His comments were vague and avoided expressing an opinion.","translation_text":"他的评论含糊不清，避免表达任何立场。"},{"id":"c","learning_text":"His comments were frank rather than unkind or severe.","translation_text":"他的评论是坦率的，而不是尖刻的。"},{"id":"d","learning_text":"His comments were polite but completely dishonest.","translation_text":"他的评论虽然礼貌，却完全不诚实。"}]'::jsonb, 'c', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-020', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'chinese_translation', 'zh', 'precise-word-choice', 'Choose the most accurate Simplified Chinese translation of: “An incidental remark led to a useful discussion.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"A formal announcement led to a useful discussion.","translation_text":"一项正式声明引发了一场有益的讨论。"},{"id":"b","learning_text":"A carefully prepared proposal led to a useful discussion.","translation_text":"一份经过精心准备的提案引发了一场有益的讨论。"},{"id":"c","learning_text":"A public criticism led to a useful discussion.","translation_text":"一场公开批评引发了一场有益的讨论。"},{"id":"d","learning_text":"A passing comment led to a useful discussion.","translation_text":"一句随口提及的话引发了一场有益的讨论。"}]'::jsonb, 'd', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-advanced-zh-021', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'chinese_translation', 'zh', 'precise-word-choice', 'Choose the most accurate Simplified Chinese translation of: “She was reluctant to disclose the details before the review.”', '请选择最准确、最自然的简体中文翻译。', '[{"id":"a","learning_text":"She was unwilling to reveal the details before the review.","translation_text":"在审查之前，她不愿透露这些细节。"},{"id":"b","learning_text":"She willingly published every detail before the review.","translation_text":"在审查之前，她主动公开了所有细节。"},{"id":"c","learning_text":"She asked for more details before the review.","translation_text":"在审查之前，她要求提供更多细节。"},{"id":"d","learning_text":"She forgot the details before the review took place.","translation_text":"审查开始之前，她忘记了这些细节。"}]'::jsonb, 'a', 'The correct option preserves the meaning and context of the English sentence.', '正确选项保留了英文句子的主要含义和语境；其他选项改变了关键信息。', 'approved', pg_catalog.now()),
  ('quiz-beginner-def-001', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'word_definition', 'en', 'descriptive-adjectives', 'Which definition best matches the word “exciting”?', '以下哪项最符合单词“exciting”的含义？', '[{"id":"a","learning_text":"Causing strong interest or enthusiasm.","translation_text":"引起强烈兴趣或热情的。"},{"id":"b","learning_text":"Making someone feel sleepy and relaxed.","translation_text":"使人感到困倦和放松的。"},{"id":"c","learning_text":"Full of people with very little space.","translation_text":"人很多、空间很拥挤的。"},{"id":"d","learning_text":"Having a very pleasant taste.","translation_text":"味道非常好的。"}]'::jsonb, 'a', 'Exciting describes something that creates strong interest, enthusiasm or anticipation.', 'Exciting形容能引起强烈兴趣、热情或期待的事物。', 'approved', pg_catalog.now()),
  ('quiz-beginner-def-002', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'word_definition', 'en', 'descriptive-adjectives', 'Which definition best matches the word “beautiful”?', '以下哪项最符合单词“beautiful”的含义？', '[{"id":"a","learning_text":"Very pleasing to look at.","translation_text":"看起来非常赏心悦目的。"},{"id":"b","learning_text":"Full of people and activity.","translation_text":"人很多、活动频繁的。"},{"id":"c","learning_text":"Pleasant to eat or drink.","translation_text":"吃起来或喝起来味道很好的。"},{"id":"d","learning_text":"Making the body feel relaxed.","translation_text":"让身体感到放松的。"}]'::jsonb, 'a', 'Beautiful describes a person, place or thing that is very pleasing to look at.', 'Beautiful形容人、地方或事物非常好看、令人赏心悦目。', 'approved', pg_catalog.now()),
  ('quiz-beginner-def-003', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'word_definition', 'en', 'descriptive-adjectives', 'Which definition best matches the word “crowded”?', '以下哪项最符合单词“crowded”的含义？', '[{"id":"a","learning_text":"Full of people, with little free space.","translation_text":"人很多、空余空间很少的。"},{"id":"b","learning_text":"Quiet and almost empty.","translation_text":"安静而且几乎没有人的。"},{"id":"c","learning_text":"Easy to carry from place to place.","translation_text":"容易从一个地方搬到另一个地方的。"},{"id":"d","learning_text":"Pleasant to look at.","translation_text":"看起来令人赏心悦目的。"}]'::jsonb, 'a', 'Crowded describes a place where many people are close together and space is limited.', 'Crowded形容许多人聚集在一起、空间有限的地方。', 'approved', pg_catalog.now()),
  ('quiz-beginner-def-004', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'word_definition', 'en', 'descriptive-adjectives', 'Which definition best matches the word “comfortable”?', '以下哪项最符合单词“comfortable”的含义？', '[{"id":"a","learning_text":"Making you feel relaxed and physically at ease.","translation_text":"让你感到放松、身体舒适的。"},{"id":"b","learning_text":"Costing a lot of money.","translation_text":"价格很高的。"},{"id":"c","learning_text":"Causing strong excitement.","translation_text":"令人非常兴奋的。"},{"id":"d","learning_text":"Having many people in a small space.","translation_text":"许多人挤在狭小空间里的。"}]'::jsonb, 'a', 'Comfortable describes something that makes you feel relaxed or physically at ease.', 'Comfortable形容让人感到放松或身体舒适的事物。', 'approved', pg_catalog.now()),
  ('quiz-beginner-def-005', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'word_definition', 'en', 'descriptive-adjectives', 'Which definition best matches the word “delicious”?', '以下哪项最符合单词“delicious”的含义？', '[{"id":"a","learning_text":"Having a very pleasant taste.","translation_text":"味道非常好的。"},{"id":"b","learning_text":"Very quiet and peaceful.","translation_text":"非常安静、平和的。"},{"id":"c","learning_text":"Difficult to understand.","translation_text":"难以理解的。"},{"id":"d","learning_text":"Full of people.","translation_text":"人很多的。"}]'::jsonb, 'a', 'Delicious describes food or drink that tastes very good.', 'Delicious形容食物或饮料味道非常好。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-def-001', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'word_definition', 'en', 'phrasal-verbs-in-context', 'Which definition best matches the word “give up”?', '以下哪项最符合短语“give up”的含义？', '[{"id":"a","learning_text":"To stop trying to do something.","translation_text":"停止尝试做某事。"},{"id":"b","learning_text":"To postpone an activity.","translation_text":"把某项活动推迟。"},{"id":"c","learning_text":"To discover something new.","translation_text":"发现新的事物。"},{"id":"d","learning_text":"To continue despite difficulty.","translation_text":"尽管困难仍继续。"}]'::jsonb, 'a', 'Give up means to stop trying or to stop doing something.', 'Give up表示停止尝试或停止做某事。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-def-002', 1, 'en', 'zh', 'i-phrasal', 'phrasal-verbs', 'intermediate', 'word_definition', 'en', 'phrasal-verbs-in-context', 'Which definition best matches the word “put off”?', '以下哪项最符合短语“put off”的含义？', '[{"id":"a","learning_text":"To delay something until a later time.","translation_text":"把某事推迟到较晚的时间。"},{"id":"b","learning_text":"To complete something early.","translation_text":"提前完成某事。"},{"id":"c","learning_text":"To explain something clearly.","translation_text":"清楚地解释某事。"},{"id":"d","learning_text":"To accept an invitation.","translation_text":"接受邀请。"}]'::jsonb, 'a', 'Put off means to postpone or delay an event or activity.', 'Put off表示推迟某个事件或活动。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-def-003', 1, 'en', 'zh', 'i-collocations', 'collocations', 'intermediate', 'word_definition', 'en', 'natural-collocations', 'Which definition best matches the word “collocation”?', '以下哪项最符合单词“collocation”的含义？', '[{"id":"a","learning_text":"A combination of words that commonly occur together.","translation_text":"经常一起出现的词语组合。"},{"id":"b","learning_text":"A word that has the opposite meaning of another.","translation_text":"与另一个词意思相反的词。"},{"id":"c","learning_text":"A sentence with no verb.","translation_text":"没有动词的句子。"},{"id":"d","learning_text":"A rule for spelling every plural noun.","translation_text":"所有复数名词的拼写规则。"}]'::jsonb, 'a', 'A collocation is a natural or common combination of words, such as “make a decision”.', 'Collocation指自然或常见的词语搭配，例如“make a decision”。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-def-004', 1, 'en', 'zh', 'i-word-families', 'word-formation', 'intermediate', 'word_definition', 'en', 'word-formation-and-confusable-forms', 'Which definition best matches the word “clarification”?', '以下哪项最符合单词“clarification”的含义？', '[{"id":"a","learning_text":"An explanation that makes something easier to understand.","translation_text":"让某事更容易理解的说明。"},{"id":"b","learning_text":"A statement that makes something less certain.","translation_text":"让某事变得更不确定的陈述。"},{"id":"c","learning_text":"A decision to stop an activity.","translation_text":"停止某项活动的决定。"},{"id":"d","learning_text":"A description of a future possibility.","translation_text":"对未来可能性的描述。"}]'::jsonb, 'a', 'Clarification is extra information or an explanation that makes a point clearer.', 'Clarification指让某个观点更清楚的补充信息或解释。', 'approved', pg_catalog.now()),
  ('quiz-intermediate-def-005', 1, 'en', 'zh', 'i-conditionals', 'conditional-sentences', 'intermediate', 'word_definition', 'en', 'conditional-meaning-and-forms', 'Which definition best matches the word “hypothetical”?', '以下哪项最符合单词“hypothetical”的含义？', '[{"id":"a","learning_text":"Based on an imagined situation rather than a confirmed fact.","translation_text":"基于想象情境，而非已确认事实的。"},{"id":"b","learning_text":"Proven by direct measurement.","translation_text":"通过直接测量证实的。"},{"id":"c","learning_text":"Likely to happen at a fixed time.","translation_text":"很可能在固定时间发生的。"},{"id":"d","learning_text":"Describing something that happened regularly in the past.","translation_text":"描述过去经常发生的事情的。"}]'::jsonb, 'a', 'Hypothetical describes an imagined or assumed situation used for discussion or reasoning.', 'Hypothetical形容用于讨论或推理的想象或假设情境。', 'approved', pg_catalog.now()),
  ('quiz-advanced-def-001', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'word_definition', 'en', 'precise-word-choice', 'Which definition best matches the word “imply”?', '以下哪项最符合单词“imply”的含义？', '[{"id":"a","learning_text":"To suggest something without stating it directly.","translation_text":"不直接说明，而是暗示某事。"},{"id":"b","learning_text":"To reach a conclusion from available evidence.","translation_text":"根据现有证据得出结论。"},{"id":"c","learning_text":"To reject an idea openly.","translation_text":"公开否定某个想法。"},{"id":"d","learning_text":"To repeat a statement word for word.","translation_text":"逐字重复一项陈述。"}]'::jsonb, 'a', 'To imply is to communicate an idea indirectly rather than state it explicitly.', 'Imply表示间接传达某个意思，而不是明确说出来。', 'approved', pg_catalog.now()),
  ('quiz-advanced-def-002', 1, 'en', 'zh', 'a-near-synonyms', 'precise-vocabulary', 'advanced', 'word_definition', 'en', 'precise-word-choice', 'Which definition best matches the word “infer”?', '以下哪项最符合单词“infer”的含义？', '[{"id":"a","learning_text":"To reach a conclusion from evidence or clues.","translation_text":"根据证据或线索得出结论。"},{"id":"b","learning_text":"To suggest an idea without saying it.","translation_text":"不直接说出某个想法，而是暗示它。"},{"id":"c","learning_text":"To remove information from a report.","translation_text":"从报告中删除信息。"},{"id":"d","learning_text":"To make a statement less certain.","translation_text":"降低陈述确定性的表达方式。"}]'::jsonb, 'a', 'To infer is to work out a conclusion from evidence, clues or reasoning.', 'Infer表示根据证据、线索或推理得出结论。', 'approved', pg_catalog.now()),
  ('quiz-advanced-def-003', 1, 'en', 'zh', 'a-hedging', 'academic-professional-english', 'advanced', 'word_definition', 'en', 'qualified-academic-claims', 'Which definition best matches the word “hedging”?', '以下哪项最符合语言学中“hedging”的含义？', '[{"id":"a","learning_text":"Using language to make a claim less absolute or certain.","translation_text":"使用语言让某项主张不那么绝对或确定。"},{"id":"b","learning_text":"Repeating a claim to make it sound stronger.","translation_text":"重复某项主张以增强语气。"},{"id":"c","learning_text":"Changing a sentence into a question.","translation_text":"把句子改成疑问句。"},{"id":"d","learning_text":"Removing all supporting evidence from an argument.","translation_text":"从论证中删除所有支持证据。"}]'::jsonb, 'a', 'Hedging uses cautious language, such as “may” or “suggests”, to express appropriate uncertainty.', 'Hedging指使用“may”或“suggests”等谨慎措辞，恰当地表达不确定性。', 'approved', pg_catalog.now()),
  ('quiz-advanced-def-004', 1, 'en', 'zh', 'a-inversion', 'advanced-grammar', 'advanced', 'word_definition', 'en', 'formal-inversion', 'Which definition best matches the word “inversion”?', '以下哪项最符合语法术语“inversion”的含义？', '[{"id":"a","learning_text":"Changing the usual word order, often placing an auxiliary verb before the subject.","translation_text":"改变通常的语序，常把助动词放在主语之前。"},{"id":"b","learning_text":"Leaving out a word that is understood from context.","translation_text":"省略一个可从语境理解的词。"},{"id":"c","learning_text":"Joining two independent clauses with a conjunction.","translation_text":"用连词连接两个独立分句。"},{"id":"d","learning_text":"Changing a verb into its past participle form.","translation_text":"把动词变成过去分词形式。"}]'::jsonb, 'a', 'Inversion changes the usual word order; formal English may place an auxiliary verb before the subject.', 'Inversion指改变通常的语序；正式英语中可能把助动词放在主语之前。', 'approved', pg_catalog.now()),
  ('quiz-advanced-def-005', 1, 'en', 'zh', 'a-idioms', 'idioms-fixed-expressions', 'advanced', 'word_definition', 'en', 'figurative-idioms', 'Which definition best matches the word “on the same page”?', '以下哪项最符合短语“on the same page”的含义？', '[{"id":"a","learning_text":"Having the same understanding or agreement about something.","translation_text":"对某事有相同的理解或共识。"},{"id":"b","learning_text":"Reading the same physical page in a book.","translation_text":"阅读书本中同一张页面。"},{"id":"c","learning_text":"Working in different places without communicating.","translation_text":"在不同地点工作且互不沟通。"},{"id":"d","learning_text":"Finishing a task before the agreed time.","translation_text":"在约定时间之前完成任务。"}]'::jsonb, 'a', 'On the same page means sharing the same understanding or agreement.', 'On the same page表示彼此理解一致或达成共识。', 'approved', pg_catalog.now()),
  ('quiz-beginner-zh-word-001', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'chinese_translation', 'zh', 'descriptive-adjectives', 'Which is the correct Simplified Chinese translation of “exciting”?', '以下哪项是“exciting”的正确简体中文翻译？', '[{"id":"a","learning_text":"exciting","translation_text":"令人兴奋的"},{"id":"b","learning_text":"beautiful","translation_text":"美丽的"},{"id":"c","learning_text":"crowded","translation_text":"拥挤的"},{"id":"d","learning_text":"delicious","translation_text":"美味的"}]'::jsonb, 'a', 'The correct translation of “exciting” in this vocabulary context is “令人兴奋的”.', '在本词汇语境中，“exciting”的正确翻译是“令人兴奋的”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-zh-word-002', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'chinese_translation', 'zh', 'descriptive-adjectives', 'Which is the correct Simplified Chinese translation of “beautiful”?', '以下哪项是“beautiful”的正确简体中文翻译？', '[{"id":"a","learning_text":"beautiful","translation_text":"美丽的"},{"id":"b","learning_text":"comfortable","translation_text":"舒适的"},{"id":"c","learning_text":"expensive","translation_text":"昂贵的"},{"id":"d","learning_text":"boring","translation_text":"无聊的"}]'::jsonb, 'a', 'The correct translation of “beautiful” in this vocabulary context is “美丽的”.', '在本词汇语境中，“beautiful”的正确翻译是“美丽的”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-zh-word-003', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'chinese_translation', 'zh', 'descriptive-adjectives', 'Which is the correct Simplified Chinese translation of “crowded”?', '以下哪项是“crowded”的正确简体中文翻译？', '[{"id":"a","learning_text":"crowded","translation_text":"拥挤的"},{"id":"b","learning_text":"quiet","translation_text":"安静的"},{"id":"c","learning_text":"friendly","translation_text":"友好的"},{"id":"d","learning_text":"useful","translation_text":"有用的"}]'::jsonb, 'a', 'The correct translation of “crowded” in this vocabulary context is “拥挤的”.', '在本词汇语境中，“crowded”的正确翻译是“拥挤的”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-zh-word-004', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'chinese_translation', 'zh', 'descriptive-adjectives', 'Which is the correct Simplified Chinese translation of “comfortable”?', '以下哪项是“comfortable”的正确简体中文翻译？', '[{"id":"a","learning_text":"comfortable","translation_text":"舒适的"},{"id":"b","learning_text":"dangerous","translation_text":"危险的"},{"id":"c","learning_text":"delicious","translation_text":"美味的"},{"id":"d","learning_text":"beautiful","translation_text":"美丽的"}]'::jsonb, 'a', 'The correct translation of “comfortable” in this vocabulary context is “舒适的”.', '在本词汇语境中，“comfortable”的正确翻译是“舒适的”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-zh-word-005', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'chinese_translation', 'zh', 'descriptive-adjectives', 'Which is the correct Simplified Chinese translation of “delicious”?', '以下哪项是“delicious”的正确简体中文翻译？', '[{"id":"a","learning_text":"delicious","translation_text":"美味的"},{"id":"b","learning_text":"exciting","translation_text":"令人兴奋的"},{"id":"c","learning_text":"crowded","translation_text":"拥挤的"},{"id":"d","learning_text":"expensive","translation_text":"昂贵的"}]'::jsonb, 'a', 'The correct translation of “delicious” in this vocabulary context is “美味的”.', '在本词汇语境中，“delicious”的正确翻译是“美味的”。', 'approved', pg_catalog.now()),
  ('quiz-beginner-zh-word-006', 1, 'en', 'zh', 'b-verb-combinations', 'everyday-vocabulary', 'beginner', 'chinese_translation', 'zh', 'descriptive-adjectives', 'Which is the correct Simplified Chinese translation of “friendly”?', '以下哪项是“friendly”的正确简体中文翻译？', '[{"id":"a","learning_text":"friendly","translation_text":"友好的"},{"id":"b","learning_text":"quiet","translation_text":"安静的"},{"id":"c","learning_text":"boring","translation_text":"无聊的"},{"id":"d","learning_text":"comfortable","translation_text":"舒适的"}]'::jsonb, 'a', 'The correct translation of “friendly” in this vocabulary context is “友好的”.', '在本词汇语境中，“friendly”的正确翻译是“友好的”。', 'approved', pg_catalog.now()),
